import type { BadgeVariant } from "../../utils/dataViews/types";

type TorchBadgeColor =
  "gray" | "slate" | "red" | "orange" | "yellow" | "green" | "ocean" | "blue" | "purple" | "rose";

type TorchBadgeStyle = "solid" | "subtle";

export type ResolvedBadgeProps = {
  color: TorchBadgeColor;
  badgeStyle: TorchBadgeStyle;
};

/**
 * Map the DataViews `BadgeVariant` set onto Glare `Badge` props.
 * Defaults to `subtle` style (glare's native default — colored dot + subtle bg).
 * The legacy "Light" / "navy" / "bluePurple" variants explicitly request solid
 * fills, kept distinct for backwards compat with the data-views examples.
 */
export function resolveBadgeVariant(variant?: BadgeVariant): ResolvedBadgeProps {
  switch (variant) {
    case "green":
      return { color: "green", badgeStyle: "subtle" };
    case "greenLight":
      return { color: "green", badgeStyle: "subtle" };
    case "cocktailGreen":
      return { color: "green", badgeStyle: "solid" };
    case "yellow":
      return { color: "yellow", badgeStyle: "subtle" };
    case "redOrange":
      return { color: "orange", badgeStyle: "subtle" };
    case "redLight":
      return { color: "red", badgeStyle: "subtle" };
    case "rose":
      return { color: "rose", badgeStyle: "subtle" };
    case "purple":
      return { color: "purple", badgeStyle: "subtle" };
    case "bluePurple":
      return { color: "purple", badgeStyle: "solid" };
    case "blue":
      return { color: "blue", badgeStyle: "subtle" };
    case "navy":
      return { color: "blue", badgeStyle: "solid" };
    case "highlight":
      return { color: "yellow", badgeStyle: "subtle" };
    case "gray":
    default:
      return { color: "gray", badgeStyle: "subtle" };
  }
}

"use client";

import React from "react";
import { cn } from "../../utils/cn";
import { getByPath } from "../../utils/dataViews/path";
import type { CurrencyOptions, FieldConfig, Row } from "../../utils/dataViews/types";
import { Avatar, AvatarFallback, AvatarImage } from "../Avatar";
import { Badge } from "../Badge";
import { resolveBadgeVariant } from "./badge";

/**
 * Paints one field of one row.
 *
 * This is the whole of DataViews' relationship with your data: read the value at `field.path` and
 * turn it into pixels. Every view — table cell, board card, inbox row, tree node — goes through
 * here, so a field looks the same wherever it appears and there is one place to add a type.
 *
 * `field.render` wins over `field.type`, so anything not covered below is a one-line escape hatch
 * rather than a reason to extend `FieldType`.
 */
export function Cell({
  field,
  row,
  className,
}: {
  field: FieldConfig;
  row: Row;
  className?: string;
}) {
  const value = getByPath(row, field.path);

  if (field.render) return <>{field.render(value, row)}</>;

  const type = field.type ?? "text";
  if (type === "hidden") return null;

  // `boolean` and `progress-bar` render something meaningful for a missing value — false, and an
  // empty bar — so they are the two types that never show the placeholder.
  if (isBlank(value) && type !== "boolean" && type !== "progress-bar") {
    return className ? <span className={className}>{NULL_PLACEHOLDER}</span> : NULL_PLACEHOLDER;
  }

  const content = paint(type, field, row, value);
  if (content === null) return null;
  return className ? <span className={className}>{content}</span> : <>{content}</>;
}

const NULL_PLACEHOLDER = <span className="text-content-presentation-global-tertiary">-</span>;

/**
 * An empty array counts as blank. It has to: `String([])` is `""`, so without this an `image`
 * field handed `[]` renders `<img src="">`, which the browser resolves to the current page and
 * re-downloads it. `badge-array` checks `Array.isArray` before this ever applies.
 */
function isBlank(value: unknown) {
  if (Array.isArray(value)) return value.length === 0;
  return value === undefined || value === null || value === "";
}

// ─── Formatting helpers ───────────────────────────────────────────────────────

function formatWithToken(d: Date, token: string): string {
  const pad = (n: number) => String(n).padStart(2, "0");
  return token
    .replace(/YYYY/g, String(d.getFullYear()))
    .replace(/MM/g, pad(d.getMonth() + 1))
    .replace(/DD/g, pad(d.getDate()))
    .replace(/HH/g, pad(d.getHours()))
    .replace(/mm/g, pad(d.getMinutes()))
    .replace(/ss/g, pad(d.getSeconds()));
}

function toInitials(s: string): string {
  if (!s) return "?";
  const parts = String(s).trim().split(/\s+/).slice(0, 2);
  return parts.map((p) => p[0]?.toUpperCase() ?? "").join("") || "?";
}

function IconNode({ icon }: { icon: string }) {
  if (/^ri-/.test(icon)) return <i className={icon} />;
  return <span aria-hidden>{icon}</span>;
}

// ─── The type switch ──────────────────────────────────────────────────────────

function paint(
  type: NonNullable<FieldConfig["type"]>,
  field: FieldConfig,
  row: Row,
  value: unknown,
): React.ReactNode {
  switch (type) {
    case "number": {
      return (
        <span className="font-mono text-content-presentation-global-primary">
          {typeof value === "number" ? value.toLocaleString() : String(value)}
        </span>
      );
    }

    case "date":
      return <span className="text-content-presentation-global-primary">{String(value)}</span>;

    case "date-format": {
      const opts = field.dateFormat;
      let formatted = String(value);
      try {
        const d = value instanceof Date ? value : new Date(value as string | number);
        if (!Number.isNaN(d.getTime())) {
          if (typeof opts === "object" && opts) {
            formatted = new Intl.DateTimeFormat(undefined, opts).format(d);
          } else if (typeof opts === "string") {
            formatted = formatWithToken(d, opts);
          } else {
            formatted = new Intl.DateTimeFormat(undefined, {
              year: "numeric",
              month: "short",
              day: "numeric",
            }).format(d);
          }
        }
      } catch {
        /* fall through to the raw string */
      }
      return <span className="text-content-presentation-global-primary">{formatted}</span>;
    }

    case "boolean": {
      const isTrue = !!value;
      const variant = isTrue ? (field.trueVariant ?? "green") : (field.falseVariant ?? "gray");
      return (
        <Badge
          {...resolveBadgeVariant(variant)}
          label={isTrue ? (field.trueLabel ?? "Yes") : (field.falseLabel ?? "No")}
          size="S"
        />
      );
    }

    case "enum-badge": {
      const key = String(value);
      const variant = field.variants?.[key] ?? field.defaultVariant ?? "gray";
      return <Badge {...resolveBadgeVariant(variant)} label={key} size="S" />;
    }

    case "badge-array": {
      const badgeProps = resolveBadgeVariant(field.variant ?? "blue");
      if (!Array.isArray(value)) {
        return <Badge {...badgeProps} label={String(value)} size="XS" />;
      }
      const limit = field.limit ?? value.length;
      const head = value.slice(0, limit);
      const overflow = value.length - head.length;
      return (
        <div className="flex flex-wrap gap-1">
          {/* Keyed by position, not by value — a badge-array is free to repeat one. */}
          {head.map((v, i) => (
            <Badge key={i} {...badgeProps} label={String(v)} size="XS" />
          ))}
          {overflow > 0 && (
            <Badge {...resolveBadgeVariant("gray")} label={`+${overflow}`} size="XS" />
          )}
        </div>
      );
    }

    case "currency": {
      const num = Number(value);
      if (Number.isNaN(num)) {
        return <span className="text-content-presentation-global-primary">{String(value)}</span>;
      }
      const opts: CurrencyOptions =
        typeof field.currency === "string" ? { code: field.currency } : (field.currency ?? {});
      const plain = () =>
        `${opts.symbol ?? "$"}${num.toLocaleString(opts.locale, {
          minimumFractionDigits: opts.decimals,
          maximumFractionDigits: opts.decimals,
        })}`;

      let formatted: string;
      if (opts.code) {
        try {
          formatted = new Intl.NumberFormat(opts.locale, {
            style: "currency",
            currency: opts.code,
            minimumFractionDigits: opts.decimals,
            maximumFractionDigits: opts.decimals,
          }).format(num);
        } catch {
          formatted = plain();
        }
      } else {
        formatted = plain();
      }
      return <span className="font-semibold text-green-600">{formatted}</span>;
    }

    case "number-format": {
      const num = Number(value);
      if (Number.isNaN(num)) {
        return <span className="text-content-presentation-global-primary">{String(value)}</span>;
      }
      return (
        <span className="font-mono text-content-presentation-global-primary">
          {new Intl.NumberFormat(undefined, field.format).format(num)}
        </span>
      );
    }

    case "progress-bar": {
      const raw = Number(value);
      const num = Number.isFinite(raw) ? raw : 0;
      const pct = Math.max(0, Math.min(100, num));
      // Thresholds are percentages of the bar, not values: below `warn` is red, at or above `ok`
      // is green, and everything between is amber.
      const [warn, ok] = field.thresholds ?? [40, 70];
      const color = num >= ok ? "bg-green-500" : num >= warn ? "bg-yellow-500" : "bg-red-500";
      return (
        <div className="flex min-w-[120px] items-center gap-2">
          <div className="bg-background-presentation-form-field-primary h-2 flex-1 overflow-hidden rounded-full">
            <div className={cn("h-full transition-all", color)} style={{ width: `${pct}%` }} />
          </div>
          <span className="text-content-presentation-global-primary w-10 text-right text-xs font-medium tabular-nums">
            {Math.round(num)}%
          </span>
        </div>
      );
    }

    case "star-rating": {
      const num = Number(value);
      const max = field.max ?? 5;
      const filled = Math.max(0, Math.min(max, Math.floor(num)));
      return (
        <div className="flex items-center gap-2">
          <div className="flex">
            {Array.from({ length: max }).map((_, i) => (
              <span key={i} className={i < filled ? "text-yellow-500" : "text-gray-300"} aria-hidden>
                ★
              </span>
            ))}
          </div>
          <span className="text-sm font-semibold tabular-nums">
            {Number.isFinite(num) ? num : "-"}
          </span>
        </div>
      );
    }

    case "icon-text": {
      const icon = field.icon ?? "";
      const after = field.iconPosition === "after";
      return (
        <span className="text-content-presentation-global-primary inline-flex items-center gap-1.5">
          {!after && icon && <IconNode icon={icon} />}
          <span>{String(value)}</span>
          {after && icon && <IconNode icon={icon} />}
        </span>
      );
    }

    case "two-line": {
      const secondary = field.secondaryPath != null ? getByPath(row, field.secondaryPath) : null;
      return (
        <div className="leading-tight">
          <div className="text-content-presentation-global-primary font-semibold">
            {String(value)}
          </div>
          {secondary != null && (
            <div className="text-content-presentation-global-secondary text-xs">
              {String(secondary)}
            </div>
          )}
        </div>
      );
    }

    case "avatar": {
      const src = typeof value === "string" ? value : null;
      // Without a `fallbackPath` there is no name to derive initials from — falling back to the
      // image URL would spell them out of "ht".
      const fallbackSource = field.fallbackPath != null ? getByPath(row, field.fallbackPath) : null;
      const initials = toInitials(String(fallbackSource ?? "?"));
      return (
        <Avatar>
          {src && <AvatarImage src={src} alt={initials} />}
          <AvatarFallback>{initials}</AvatarFallback>
        </Avatar>
      );
    }

    case "link": {
      const v = String(value);
      let href = v;
      if (field.linkType === "mailto" && !v.startsWith("mailto:")) href = `mailto:${v}`;
      else if (field.linkType === "tel" && !v.startsWith("tel:")) href = `tel:${v}`;
      return (
        <a
          href={href}
          target={field.linkType === "url" ? "_blank" : undefined}
          rel={field.linkType === "url" ? "noopener noreferrer" : undefined}
          className="text-blue-600 hover:underline"
          onClick={(e) => e.stopPropagation()}
        >
          {v}
        </a>
      );
    }

    case "image":
      return (
        // eslint-disable-next-line @next/next/no-img-element -- the src is arbitrary consumer data
        <img
          src={String(value)}
          alt=""
          className="border-border-presentation-global-primary h-10 w-10 rounded border object-cover"
        />
      );

    case "text":
    default:
      return <span className="text-content-presentation-global-primary">{String(value)}</span>;
  }
}

"use client";

import { createContext, useContext } from "react";
import type {
  ColumnState,
  FieldConfig,
  FilterFieldDescriptor,
  FilterState,
  Row,
  Sort,
} from "../../utils/dataViews/types";

/**
 * Every context DataViews uses. As in `FormBuilder`, this is the only file that calls
 * `createContext` — a part never invents its own provider, so there is one place to look when
 * asking "where does this part get its data".
 */

// ─── Data ─────────────────────────────────────────────────────────────────────

export interface DataContextValue {
  /** The rows to paint, exactly as handed in. Already filtered and sorted by the app. */
  rows: readonly Row[];
  /** How to paint each field. */
  fields: readonly FieldConfig[];
  /** The visible fields, in the order the user arranged them. Resolved once by the root. */
  visibleFields: readonly FieldConfig[];
  /** Stable identity for a row — selection and drag both key off this. */
  getRowId: (row: Row, index: number) => string;
  loading: boolean;
  /** True while the *next* page is in flight — `loading` is the first one. */
  loadingMore: boolean;
  /** Whether there is a next page: derived from `rows.length < total`, never passed in. */
  hasMore: boolean;
  /** Ask for the next page. Undefined when the caller did not opt into scroll loading. */
  onLoadMore?: () => void;
}

export const DataContext = createContext<DataContextValue | null>(null);

export function useDataViewsData(): DataContextValue {
  const ctx = useContext(DataContext);
  if (!ctx) throw new Error("DataViews parts must be rendered inside <DataViews>.");
  return ctx;
}

// ─── View ─────────────────────────────────────────────────────────────────────

/** One entry in the switcher. Registered by rendering the view, never by a visibility map. */
export interface RegisteredView {
  id: string;
  label: string;
  icon?: React.ReactNode;
}

/** The root's interaction state — everything the user can change that is not a row. */
export interface ViewContextValue {
  view: string;
  setView: (id: string) => void;
  /** In the order the views were rendered. */
  views: readonly RegisteredView[];
  search: string;
  setSearch: (q: string) => void;
  sort: Sort;
  setSort: (sort: Sort) => void;
  selection: readonly string[];
  setSelection: (ids: readonly string[]) => void;
  /** The row the detail pane is showing, for the views that have one. */
  activeId: string | null;
  setActiveId: (id: string | null) => void;
  /** Column visibility and order. The panel edits these; the root paints from them. */
  columns: readonly ColumnState[];
  setColumns: (columns: readonly ColumnState[]) => void;
}

export const ViewContext = createContext<ViewContextValue | null>(null);

export function useDataViewsView(): ViewContextValue {
  const ctx = useContext(ViewContext);
  if (!ctx) throw new Error("DataViews parts must be rendered inside <DataViews>.");
  return ctx;
}

// ─── Panel ────────────────────────────────────────────────────────────────────

/**
 * Whether the settings panel is showing. Provided by the **root**, not by `Panel` — the toggle
 * lives in the header, which is `Panel`'s sibling, so neither can own the state the other needs.
 */
export interface PanelContextValue {
  open: boolean;
  setOpen: (open: boolean) => void;
}

export const PanelContext = createContext<PanelContextValue | null>(null);

export function useDataViewsPanel(): PanelContextValue {
  const ctx = useContext(PanelContext);
  if (!ctx) throw new Error("DataViews parts must be rendered inside <DataViews>.");
  return ctx;
}

/** One entry in the panel's tab strip, registered by rendering a `DataViews.Panel.Tab`. */
export interface PanelTab {
  value: string;
  label: string;
  icon?: React.ReactNode;
}

/** Which tab the panel is on. Owned by `Panel`, because only its own children care. */
export interface PanelTabsContextValue {
  tab: string;
  setTab: (tab: string) => void;
  tabs: readonly PanelTab[];
}

export const PanelTabsContext = createContext<PanelTabsContextValue | null>(null);

export function useDataViewsPanelTabs(): PanelTabsContextValue {
  const ctx = useContext(PanelTabsContext);
  if (!ctx) throw new Error("DataViews.Panel parts must be rendered inside <DataViews.Panel>.");
  return ctx;
}

// ─── Filters ──────────────────────────────────────────────────────────────────

export interface FiltersContextValue {
  filters: FilterState;
  setFilters: (filters: FilterState) => void;
  /**
   * What each filter control is, read off the `FormBuilder` children of `DataViews.Filters` —
   * never derived from the rows. The root collects them as well, so a consumer such as
   * `Filters.Presets` can resolve a field by path even when it is rendered outside `Filters`.
   */
  filterFields: readonly FilterFieldDescriptor[];
}

export const FiltersContext = createContext<FiltersContextValue | null>(null);

export function useDataViewsFilters(): FiltersContextValue {
  const ctx = useContext(FiltersContext);
  if (!ctx) throw new Error("DataViews.Filters parts must be rendered inside <DataViews.Filters>.");
  return ctx;
}

"use client";

import React, { Children, useCallback, useEffect, useMemo, useState } from "react";
import { cn } from "../../utils/cn";
import { defaultGetRowId } from "../../utils/dataViews/path";
import { emptyQuery } from "../../utils/dataViews/query";
import type {
  ColumnState,
  DataViewsQuery,
  FieldConfig,
  FilterState,
  Sort,
} from "../../utils/dataViews/types";
import {
  DataContext,
  FiltersContext,
  PanelContext,
  ViewContext,
  type RegisteredView,
} from "./context";
import { Actions, Header, PanelToggle, Search, ViewSwitch } from "./header";
import { Empty } from "./states";
import {
  isEmptyElement,
  isHeaderElement,
  isPanelElement,
  isViewElement,
  viewMetaOf,
} from "./slots";
import { collectFilterFields, Filters } from "./filters";
import { Panel } from "./panel";
import { BoardView } from "./views/board-view";
import { Detail, InboxView } from "./views/inbox-view";
import { TableView } from "./views/table-view";
import { TreeView } from "./views/tree-view";
import { useControllable } from "./hooks/useControllable";
import type { DataViewsRootProps } from "./types";

/**
 * A cheap identity for a node used only as a memo key. React elements have no stable identity
 * across renders, so an inline `<i className="ri-table-line"/>` would look new every time; the
 * element's props are what actually distinguish one icon from another.
 */
function iconKey(icon: React.ReactNode): string {
  if (icon === null || icon === undefined || typeof icon === "boolean") return "";
  if (React.isValidElement(icon)) return JSON.stringify(icon.props ?? {});
  return String(icon);
}

// ─── Root ─────────────────────────────────────────────────────────────────────

/**
 * Resolve which fields to paint and in what order.
 *
 * The old code sorted `visibleFields` at five call sites with subtly different tie-breaks. There
 * is one rule now: if `columns` is supplied it decides both visibility and order; anything not
 * mentioned in it keeps its declaration order at the end.
 */
function resolveVisibleFields(
  fields: readonly FieldConfig[],
  columns: readonly ColumnState[] | undefined,
): FieldConfig[] {
  if (!columns || columns.length === 0) {
    return fields.filter((f) => f.visible !== false && f.type !== "hidden");
  }
  const byPath = new Map(fields.map((f) => [f.path, f]));
  const ordered: FieldConfig[] = [];
  for (const col of columns) {
    const field = byPath.get(col.path);
    if (field && col.visible) ordered.push(field);
    byPath.delete(col.path);
  }
  for (const field of byPath.values()) {
    if (field.visible !== false && field.type !== "hidden") ordered.push(field);
  }
  return ordered;
}

function DataViewsRoot({
  rows,
  fields,
  children,
  getRowId = defaultGetRowId,
  total = 0,
  loading = false,
  onLoadMore,
  loadingMore = false,
  query,
  onQueryChange,
  defaultQuery,
  defaultView,
  defaultPanelOpen = false,
  onViewChange,
  onSelectionChange,
  onActiveIdChange,
  theme,
  className,
}: DataViewsRootProps) {
  const childArray = Children.toArray(children);

  // A view exists because you rendered it. `Children.toArray` drops `false`/`null`, so
  // `{canSeeTree && <DataViews.Tree/>}` un-registers that view — which is the intent.
  const viewElements = childArray.filter(isViewElement);
  const headerEl = childArray.find(isHeaderElement);
  const panelEl = childArray.find(isPanelElement);
  // Anything the root does not position itself — a `Filters` bar, a toolbar of your own — sits
  // between the header and the views, in the order you wrote it.
  // LOCAL PATCH (Contact Center): the empty slot. It must be excluded from `extras` too --
  // `extras` is the negative-space bucket, so without this the element would render twice:
  // once above the view and once as the body.
  const emptyEl = childArray.find(isEmptyElement);
  const extras = childArray.filter(
    (n) =>
      !isViewElement(n) && !isHeaderElement(n) && !isPanelElement(n) && !isEmptyElement(n),
  );

  // `viewElements` is a fresh array on every render, so memoising on its identity would never
  // hit. Key on what actually matters instead: which views are rendered and how they present.
  // `icon` is part of that — leave it out and swapping only an icon leaves a stale one showing.
  const viewKey = viewElements
    .map((el) => `${el.props.id}|${el.props.label}|${iconKey(el.props.icon)}`)
    .join(",");
  const registered = useMemo<RegisteredView[]>(
    () =>
      viewElements.map((el) => {
        const meta = viewMetaOf(el)!;
        return {
          id: el.props.id ?? meta.defaultId,
          label: el.props.label ?? meta.defaultLabel,
          icon: el.props.icon,
        };
      }),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- keyed on `viewKey`, see above
    [viewKey],
  );

  const firstId = registered[0]?.id ?? "";

  // ── The query: the only state that leaves ──────────────────────────────────
  const [currentQuery, setQuery] = useControllable<DataViewsQuery>(
    query,
    onQueryChange,
    emptyQuery(defaultQuery),
  );

  /**
   * Change part of the query.
   *
   * Anything that changes *which* rows match starts a new result set, so the page goes back to 1 —
   * filter down to three rows while sitting on page 4 and there is no page 4 to stay on. Only the
   * component can do this: by the time a caller sees the change, the two have already been
   * conflated into one object.
   */
  const patchQuery = useCallback(
    (patch: Partial<DataViewsQuery>) => {
      setQuery((prev) => {
        const changesResultSet =
          ("search" in patch && patch.search !== prev.search) ||
          ("filters" in patch && patch.filters !== prev.filters) ||
          ("sort" in patch && patch.sort !== prev.sort) ||
          ("pageSize" in patch && patch.pageSize !== prev.pageSize);
        return { ...prev, ...patch, ...(changesResultSet ? { page: 1 } : null) };
      });
    },
    [setQuery],
  );

  // ── UI state: never leaves, so it is held rather than passed ───────────────
  const [currentView, setCurrentView] = useState(defaultView ?? firstId);
  const [currentColumns, setColumns] = useState<readonly ColumnState[]>([]);
  const [currentSelection, setSelectionState] = useState<readonly string[]>([]);
  const [currentActiveId, setActiveIdState] = useState<string | null>(null);
  const [isPanelOpen, setPanelOpen] = useState(defaultPanelOpen);

  // The observers are told, not asked: they report what the component decided, so an app can act
  // on a selection or follow the open row without owning either.
  const setSelection = useCallback(
    (ids: readonly string[]) => {
      setSelectionState(ids);
      onSelectionChange?.(ids);
    },
    [onSelectionChange],
  );
  const setActiveId = useCallback(
    (id: string | null) => {
      setActiveIdState(id);
      onActiveIdChange?.(id);
    },
    [onActiveIdChange],
  );
  const setView = useCallback(
    (id: string) => {
      setCurrentView(id);
      onViewChange?.(id);
    },
    [onViewChange],
  );

  // If the active view stops being rendered, converge on the first one — in an effect, never
  // during render, so a controlled consumer's state actually catches up.
  const known = registered.some((v) => v.id === currentView);
  useEffect(() => {
    if (!known && firstId) setView(firstId);
  }, [known, firstId, setView]);

  const activeView = known ? currentView : firstId;
  const activeElement = viewElements.find(
    (el) => (el.props.id ?? viewMetaOf(el)!.defaultId) === activeView,
  );

  const visibleFields = useMemo(
    () => resolveVisibleFields(fields, currentColumns),
    [fields, currentColumns],
  );

  const dataValue = useMemo(
    () => ({
      rows,
      fields,
      visibleFields,
      getRowId,
      loading,
      loadingMore,
      // Derived, never passed: the component has both halves already, and a `hasMore` prop that
      // disagreed with the rows on screen would be a second source of truth for the same fact.
      hasMore: rows.length < total,
      onLoadMore,
    }),
    [rows, fields, visibleFields, getRowId, loading, loadingMore, total, onLoadMore],
  );

  const setSearch = useCallback((search: string) => patchQuery({ search }), [patchQuery]);
  const setSort = useCallback((sort: Sort) => patchQuery({ sort }), [patchQuery]);

  const viewValue = useMemo(
    () => ({
      view: activeView,
      setView,
      views: registered,
      search: currentQuery.search,
      setSearch,
      sort: currentQuery.sort,
      setSort,
      selection: currentSelection,
      setSelection,
      activeId: currentActiveId,
      setActiveId,
      columns: currentColumns,
      setColumns,
    }),
    [
      activeView,
      setView,
      registered,
      currentQuery.search,
      setSearch,
      currentQuery.sort,
      setSort,
      currentSelection,
      setSelection,
      currentActiveId,
      setActiveId,
      currentColumns,
      setColumns,
    ],
  );

  const panelValue = useMemo(
    () => ({ open: isPanelOpen, setOpen: setPanelOpen }),
    [isPanelOpen, setPanelOpen],
  );

  // The descriptors as well as the value: a consumer such as `Filters.Presets` resolves a field by
  // path, and may be rendered outside `Filters` — above the table, in a toolbar — where it cannot
  // reach the context `Filters` provides to its own children.
  const filterFields = useMemo(() => collectFilterFields(children), [children]);

  const setFilters = useCallback(
    (filters: FilterState) => patchQuery({ filters }),
    [patchQuery],
  );

  const filtersValue = useMemo(
    () => ({ filters: currentQuery.filters, setFilters, filterFields }),
    [currentQuery.filters, setFilters, filterFields],
  );

  // The active view is what renders, unless a `DataViews.Empty` was supplied and the query has
  // SETTLED on nothing — then the caller's empty state takes the view's place entirely.
  //
  // LOCAL PATCH (Contact Center). `!loading` is the whole reason this is safe: rows are empty
  // while the first page is still in flight, so without it the empty state would replace the
  // view's skeleton and announce "nothing matched" before anything had been asked for — the
  // exact failure that made upstream ship no `Empty` at all (see `states.tsx`). Loading is still
  // answered by the view's own skeleton; only a settled empty result swaps the body.
  const body = emptyEl && !loading && rows.length === 0 ? emptyEl : activeElement;

  return (
    <DataContext.Provider value={dataValue}>
      <ViewContext.Provider value={viewValue}>
        <PanelContext.Provider value={panelValue}>
          <FiltersContext.Provider value={filtersValue}>
            <div
              data-theme={theme}
              className={cn(
                // The shell is always black: the dark header and the config rail sit on it, and
                // the Master Container is the light surface inside. `overflow-hidden` traps child
                // overflow — without it a tall panel body escapes and adds a page-level scrollbar
                // on top of the panel's own.
                "flex h-full min-h-0 gap-2 overflow-hidden bg-black",
                "text-content-presentation-global-primary",
                className,
              )}
            >
              {/* Left column: header + content. Shrinks as the panel expands. */}
              <div className="flex min-w-0 flex-1 flex-col gap-2">
                {headerEl}
                <main className="flex min-h-0 flex-1 overflow-hidden">
                  {/* Master Container. It carries the surface — a form base and a 16px radius —
                      so views paint over it where they want a different colour (the board reads
                      grey, the split views black) and anything the root positions around one
                      inherits it rather than landing on the black shell.

                      No border: Figma draws one, but every view already brings its own edge — the
                      table and the split views each draw their own panel border — so it only ever
                      read as a second outline around the first. */}
                  <div className="bg-background-presentation-form-base flex flex-1 overflow-hidden rounded-[16px]">
                    {/* Clip the scrollable surface to the parent radius minus its 1px border
                        (16 − 1). At the full 16px the opaque view background sits flush with the
                        outer edge and bleeds past it as a hairline on the straight sides. */}
                    <div className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-[15px]">
                      {/* Anything the root does not position itself — a `Filters` bar, a toolbar
                          of your own — sits above the view and *inside* the light surface, since
                          its controls are host-themed and would be stranded on the black shell. */}
                      {extras.length > 0 && (
                        <div className="bg-background-presentation-form-base shrink-0">{extras}</div>
                      )}
                      {/* A column, so the active view stretches to the full width. As a row it
                          would size each view to its content and leave the shell showing beside
                          a narrow one. */}
                      <div className="flex min-h-0 flex-1 flex-col overflow-auto">{body}</div>
                    </div>
                  </div>
                </main>
              </div>

              {/* The rail is a sibling of the content, not a layer over it, so opening it narrows
                  the view rather than covering it. */}
              {panelEl}
            </div>
          </FiltersContext.Provider>
        </PanelContext.Provider>
      </ViewContext.Provider>
    </DataContext.Provider>
  );
}

/**
 * DataViews — a compound, composition-based multi-view data surface. Author a screen as JSX:
 *
 * ```tsx
 * <DataViews rows={rows} fields={fields} total={total} onQueryChange={setQuery}>
 *   <DataViews.Header title="Orders">
 *     <DataViews.ViewSwitch />
 *     <DataViews.Search />
 *   </DataViews.Header>
 *   <DataViews.Table />
 *   <DataViews.Board groups={groups} />
 * </DataViews>
 * ```
 *
 * A view exists **iff you render it** — there is no visibility map. DataViews is pure UI: it
 * never filters, searches, sorts, groups or mutates. Hand it rows and it paints them; it hands
 * you back what the user did so you can go and query.
 */
export const DataViews = Object.assign(DataViewsRoot, {
  // shell
  Header,
  ViewSwitch,
  Search,
  Actions,
  PanelToggle,
  // panels
  Panel,
  Filters,
  // views
  Table: TableView,
  Board: BoardView,
  Inbox: InboxView,
  Tree: TreeView,
  Detail,
  // states
  Empty,
  // paging
});

"use client";

import React from "react";
import { fieldKindOf } from "../../FormBuilder";
import type { FilterFieldDescriptor } from "../../../utils/dataViews/types";
import { toName } from "./values";
import { Labelled } from "./labelled";

/** How a FormBuilder field's value becomes a filter. Fields not listed here are not filters. */
const AS_FILTER = {
  text: { kind: "text" } as const,
  choice: { kind: "choice", single: true } as const,
  multiChoice: { kind: "choice", single: false } as const,
  date: { kind: "date" } as const,
  slider: { kind: "number" } as const,
};

/**
 * Walk the children and describe every FormBuilder field among them.
 *
 * This is what `fields` used to be, except it is read from the controls you wrote rather than
 * declared twice. The walk follows `props.children`, so a field stays visible through a plain
 * wrapper; it cannot see through a component that builds the element itself, which is the same
 * limitation the layout markers have.
 *
 * `Checkbox`, `Number`, `File` and friends have no filter meaning — a boolean is not a query and a
 * file is not a value you can filter by — so they render but contribute nothing. `Filters.Custom`
 * is the way to drive a filter no FormBuilder field covers.
 */
export function collectFilterFields(children: React.ReactNode): FilterFieldDescriptor[] {
  const out: FilterFieldDescriptor[] = [];
  const seen = new Set<string>();

  const walk = (node: React.ReactNode) => {
    if (Array.isArray(node)) {
      node.forEach(walk);
      return;
    }
    if (!React.isValidElement(node)) return;

    const props = node.props as {
      name?: string;
      label?: React.ReactNode;
      min?: number;
      max?: number;
      children?: React.ReactNode;
    };
    const kind = fieldKindOf(node);
    const as = kind ? AS_FILTER[kind as keyof typeof AS_FILTER] : undefined;

    if (as && props.name && !seen.has(props.name)) {
      seen.add(props.name);
      out.push({
        path: props.name,
        label: typeof props.label === "string" ? props.label : undefined,
        ...as,
        ...(as.kind === "number" ? { min: props.min ?? 0, max: props.max ?? 100 } : null),
      });
    }

    walk(props.children);
  };

  walk(children);
  return out;
}

/**
 * Render the children, with two changes to every field.
 *
 * The `name` is escaped, because RHF reads `customer.name` as object nesting — the author writes
 * the real path and `FilterState` stays keyed by it. Anything calling `setValue` on a filter has
 * to use `toName(path)` for the same reason.
 *
 * The `label` moves out of the field and into `Labelled` above it: `"bare"` mode exists precisely
 * to drop `FieldSection`'s label row, so a label left on the field would simply vanish.
 */
export function renderFields(children: React.ReactNode): React.ReactNode {
  return React.Children.map(children, (child) => {
    if (!React.isValidElement(child)) return child;

    const props = child.props as { name?: string; label?: React.ReactNode; children?: React.ReactNode };

    if (fieldKindOf(child) && props.name) {
      return (
        <Labelled label={props.label}>
          {React.cloneElement(child, { name: toName(props.name), label: undefined } as never)}
        </Labelled>
      );
    }

    // Not a field — recurse so a control inside a wrapper still gets its name escaped.
    if (props.children) {
      return React.cloneElement(child, {} as never, renderFields(props.children));
    }
    return child;
  });
}

"use client";

import { formatPathLabel } from "../../../utils/dataViews/path";
import type { FilterValue } from "../../../utils/dataViews/types";
import { useDataViewsFilters } from "../context";
import { Labelled } from "./labelled";
import type { FilterCustomProps } from "../types";

/**
 * `Filters.Custom` — the escape hatch. Renders whatever you return against this filter's slot in
 * `FilterState`, bypassing the form entirely.
 *
 * Use it when no FormBuilder field produces the value you need — a bucket picker, a map region, a
 * tri-state toggle.
 *
 * ```tsx
 * <DataViews.Filters.Custom path="tags" render={({ value, setValue }) => (
 *   <MyTagPicker value={value as string[]} onChange={setValue} />
 * )} />
 * ```
 */
export function Custom({ path, label, render }: FilterCustomProps) {
  const { filters, setFilters } = useDataViewsFilters();
  const text = label ?? formatPathLabel(path);

  const setValue = (next: FilterValue | undefined) => {
    const copy = { ...filters };
    if (next === undefined) delete copy[path];
    else copy[path] = next;
    setFilters(copy);
  };

  return <Labelled label={text}>{render({ value: filters[path], setValue })}</Labelled>;
}

"use client";

import { useId, useMemo, useState } from "react";
import { cn } from "../../../utils/cn";
import { Button } from "../../Button";
import { ConclusionHeader } from "../../ConclusionHeader";
import { FormBuilder } from "../../FormBuilder";
import { CellContext } from "../../FormBuilder/context";
import { FiltersContext, useDataViewsFilters } from "../context";
import { collectFilterFields, renderFields } from "./children";
import { Custom } from "./custom";
import { Presets } from "./presets";
import { Sync } from "./sync";
import { toFormValues } from "./values";
import type { FiltersProps } from "../types";

/**
 * `DataViews.Filters` — the filter controls, written as a form.
 *
 * Three things to be clear about.
 *
 * **It does not filter.** It collects what the user asked for and calls `onValueChange`. Going and
 * fetching the matching rows is your job, almost certainly server-side. The rows on screen change
 * when you hand back different `rows` — never before.
 *
 * **The children are FormBuilder fields.** Not a config array describing fields — the fields
 * themselves, one JSX child each, exactly as any other form in this library is written. They
 * render through `CellContext` in `"bare"` mode: no `FieldSection` label row, no table borders,
 * errors as tooltips.
 *
 * **What each child means comes from the field, not from you.** `FormBuilder` stamps every field
 * with a `FieldKind` — see `fieldKindOf` — so a `MultiSelect` becomes a list of values, a `Slider`
 * a numeric range, a `DateRange` a date range. Nothing is inferred from the rows.
 *
 * There is no `value`/`onValueChange` here: the filters live in the root's query, and this reads
 * and writes them through `useDataViewsFilters()`. What leaves the component is `onQueryChange`.
 *
 * ```tsx
 * <DataViews.Filters>
 *   <FormBuilder.MultiSelect name="status" label="Status" options={STATUS} />
 *   <FormBuilder.Slider name="total" label="Total" range min={0} max={15000} step={100} />
 *   <DataViews.Filters.Presets for="total" items={[{ label: "Under $500", max: 500 }]} />
 * </DataViews.Filters>
 * ```
 */
function FiltersRoot({
  children,
  title = "Filters",
  description,
  clearLabel = "Clear",
  collapsible = true,
  defaultOpen = true,
  className,
}: FiltersProps) {
  const { filters, setFilters } = useDataViewsFilters();

  const fields = useMemo(() => collectFilterFields(children), [children]);

  const value = useMemo(
    () => ({ filters, setFilters, filterFields: fields }),
    [filters, setFilters, fields],
  );

  const values = useMemo(() => toFormValues(filters, fields), [filters, fields]);
  const active = Object.keys(filters).length > 0;

  const [open, setOpen] = useState(defaultOpen);
  const bodyId = useId();
  const isCollapsible = collapsible && title != null;
  const shown = !isCollapsible || open;

  return (
    <FiltersContext.Provider value={value}>
      <div
        className={cn(
          "flex shrink-0 flex-col gap-3 px-4 py-3",
          "border-border-presentation-global-primary border-b",
          className,
        )}
      >
        {(title || active) && (
          // `ConclusionHeader` renders a `<button>`, so Clear cannot live inside it — nesting a
          // button in a button is invalid and swallows the inner click. They are siblings.
          <div className="flex items-center gap-2">
            {title != null &&
              (isCollapsible ? (
                <ConclusionHeader
                  label={title}
                  open={open}
                  onOpenChange={setOpen}
                  aria-controls={bodyId}
                  className="flex-1"
                />
              ) : (
                // Reading the colour from a token rather than a `text-white` literal is what lets
                // the same controls sit in the dark rail and in the light content area.
                <h3 className="text-content-presentation-global-primary min-w-0 truncate text-[18px] font-[510] leading-[1.32] tracking-[-0.01em]">
                  {title}
                </h3>
              ))}
            {active && (
              <Button
                size="S"
                variant="BorderStyle"
                className="ms-auto"
                onClick={() => setFilters({})}
              >
                {clearLabel}
              </Button>
            )}
          </div>
        )}

        {/* Below the header *row*, not inside it — that row is a flex line holding the header and
            Clear as siblings, and the description belongs to the section, not beside the button. */}
        {description != null && (
          <p className="typography-body-small-regular text-content-presentation-global-primary">
            {description}
          </p>
        )}

        {/* `onSubmit` is required by FormBuilder but never reached — there is no submit button and
            no Enter target. Filters emit as you touch them. */}
        <FormBuilder onSubmit={() => {}} values={values} fieldDirection="vertical">
          <Sync fields={fields} />
          <CellContext.Provider value="bare">
            {/* Same fold as `Panel.Section`: a 0fr→1fr grid row, and `inert` so a collapsed
                filter's control leaves the tab order rather than staying focusable. */}
            <div
              id={bodyId}
              inert={!shown}
              aria-hidden={!shown}
              className={cn(
                "grid transition-[grid-template-rows,opacity] duration-200 ease-in-out",
                "motion-reduce:transition-none",
                shown ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
              )}
            >
              <div className="overflow-hidden">
                <div className="flex flex-wrap items-start gap-3">{renderFields(children)}</div>
              </div>
            </div>
          </CellContext.Provider>
        </FormBuilder>
      </div>
    </FiltersContext.Provider>
  );
}

/**
 * The filter surface, assembled in one place. `Presets` and `Custom` are ours because FormBuilder
 * has no field for them; everything else you write is a FormBuilder field.
 */
export const Filters = Object.assign(FiltersRoot, {
  Presets,
  Custom,
});

// The filter surface. `filters.tsx` assembles the compound; `children.tsx` is the walk that reads
// your FormBuilder fields; `values.ts` is the pure mapping between `FilterState` and form values.
export { Filters } from "./filters";
export { collectFilterFields } from "./children";

"use client";

import React from "react";

/** A label above a bare control, since `FieldSection` is exactly what "bare" removes. */
export function Labelled({ label, children }: { label?: React.ReactNode; children: React.ReactNode }) {
  return (
    // `flex-1` is what makes a control fill the width it was given rather than sitting at its
    // minimum with dead space beside it — one per line in the 260px rail, sharing the line evenly
    // in anything wider. `min-w` stays as the floor that decides where the parent wraps.
    <div className="flex min-w-[180px] flex-1 flex-col gap-1">
      {label && (
        <span className="typography-body-small-regular text-content-presentation-global-secondary">
          {label}
        </span>
      )}
      {children}
    </div>
  );
}

"use client";

import { useFormContext } from "react-hook-form";
import { cn } from "../../../utils/cn";
import type { FilterFieldDescriptor, NumberPreset } from "../../../utils/dataViews/types";
import { useDataViewsFilters } from "../context";
import { datePresets, numberPresets, toName } from "./values";
import type { FilterPresetsProps } from "../types";

/** Look up what `Filters` learned about a path, so a sibling control can target it. */
function useDescriptor(path: string): FilterFieldDescriptor | undefined {
  const { filterFields } = useDataViewsFilters();
  return filterFields.find((f) => f.path === path);
}


/**
 * `DataViews.Filters.Presets` — named shortcuts for the field named in `for`.
 *
 * FormBuilder has no field for this, and it is not a filter of its own: it writes into a sibling's
 * value. Numeric presets fill the side they do not name from that slider's bounds, so
 * `{ label: "$5k+", min: 5000 }` means "5,000 to the top" rather than "5,000 to 100".
 */
export function Presets({ for: path, items, className }: FilterPresetsProps) {
  const form = useFormContext();
  const field = useDescriptor(path);
  const name = toName(path);

  if (!field) return null;

  const shortcuts =
    field.kind === "date"
      ? datePresets(items).map((preset) => ({
          label: preset.label,
          apply: () =>
            form.setValue(name, {
              from: preset.from ? new Date(preset.from) : undefined,
              to: preset.to ? new Date(preset.to) : undefined,
            }),
        }))
      : numberPresets(items).map((preset: NumberPreset) => ({
          label: preset.label,
          apply: () => form.setValue(name, [preset.min ?? field.min ?? 0, preset.max ?? field.max ?? 100]),
        }));

  if (shortcuts.length === 0) return null;

  return (
    <div className={cn("flex flex-wrap gap-1", className)}>
      {shortcuts.map((preset) => (
        <button
          key={preset.label}
          type="button"
          onClick={preset.apply}
          className={cn(
            "typography-body-small-regular rounded-[4px] px-2 py-[2px] transition-colors",
            "text-content-presentation-global-secondary hover:bg-background-presentation-action-hover",
          )}
        >
          {preset.label}
        </button>
      ))}
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import { useWatch } from "react-hook-form";
import type { FilterFieldDescriptor } from "../../../utils/dataViews/types";
import { useDataViewsFilters } from "../context";
import { sameFilters, toFilterState } from "./values";

/**
 * Pushes what the user typed back out as `onValueChange`.
 *
 * Debounced, and guarded by an equality check: without both, `watch` → emit → new `values` →
 * re-render is a loop that swallows keystrokes mid-type.
 */
export function Sync({ fields }: { fields: readonly FilterFieldDescriptor[] }) {
  const { setFilters, filters } = useDataViewsFilters();
  const watched = useWatch();

  // Read the current filters through a ref so the effect does not re-run just because the parent
  // handed back a new (equal) object.
  const latest = useRef(filters);
  latest.current = filters;

  useEffect(() => {
    const timer = setTimeout(() => {
      // Merged onto the current state, not derived from scratch — these controls own only their
      // own paths. Anything else (a `Filters.Custom` value, a key the caller supplied) survives.
      const next = toFilterState(watched as Record<string, unknown>, fields, latest.current);
      if (!sameFilters(next, latest.current)) setFilters(next);
    }, 200);
    return () => clearTimeout(timer);
  }, [watched, fields, setFilters]);

  return null;
}

import type {
  DatePreset,
  FilterFieldDescriptor,
  FilterState,
  FilterValue,
  NumberPreset,
  Preset,
} from "../../../utils/dataViews/types";

/**
 * Translating between `FilterState` (what you receive) and react-hook-form values (what the
 * inputs speak). Pure functions, no React — the fiddly half of `Filters` is here so the component
 * itself stays readable, and so this is testable without rendering anything.
 */

/**
 * RHF reads `.` in a field name as object nesting, so a filter on `customer.name` would arrive as
 * `{ customer: { name: … } }`. Names are escaped on the way in and unescaped on the way out.
 */
export const toName = (path: string) => path.replace(/\./g, "__");

const isRange = (v: FilterValue | undefined): v is Exclude<FilterValue, string[]> =>
  !!v && !Array.isArray(v);

/** `FilterState` → the values the inputs want. */
export function toFormValues(
  filters: FilterState,
  fields: readonly FilterFieldDescriptor[],
): Record<string, unknown> {
  const out: Record<string, unknown> = {};

  for (const field of fields) {
    const value = filters[field.path];
    const name = toName(field.path);

    switch (field.kind) {
      case "choice": {
        const selected = Array.isArray(value) ? value : [];
        out[name] = field.single ? (selected[0] ?? "") : selected;
        break;
      }
      case "number": {
        const lo = field.min ?? 0;
        const hi = field.max ?? 100;
        const range = isRange(value) && value.kind === "number" ? value : undefined;
        out[name] = [range?.min ?? lo, range?.max ?? hi];
        break;
      }
      case "date": {
        const range = isRange(value) && value.kind === "date" ? value : undefined;
        out[name] = {
          from: range?.from ? new Date(range.from) : undefined,
          to: range?.to ? new Date(range.to) : undefined,
        };
        break;
      }
      case "text":
        out[name] = Array.isArray(value) ? (value[0] ?? "") : "";
        break;
    }
  }

  return out;
}

/**
 * `YYYY-MM-DD` in the **user's** timezone.
 *
 * `toISOString()` converts to UTC first, so someone east of UTC picking "today" in the calendar
 * would emit yesterday's date — an off-by-one-day filter that only reproduces in some timezones.
 */
const iso = (d: unknown) => {
  const date = d instanceof Date ? d : d ? new Date(String(d)) : null;
  if (!date || Number.isNaN(date.getTime())) return undefined;
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
};

/**
 * The inputs' values → `FilterState`.
 *
 * A control at its neutral position produces **no key at all** rather than an empty one. That
 * matters: the emitted query is a request to go and fetch, and `{ total: { min: 0, max: 100 } }`
 * when the slider has never been touched would narrow a query that the user never narrowed.
 *
 * `previous` is merged rather than replaced, and this is load-bearing: these `fields` own only
 * their own paths. `Filters.Custom` writes straight into `FilterState`, and a caller's initial
 * `filters` may carry keys no control was declared for. Rebuilding the state from `fields` alone
 * would silently drop both the moment any control changed.
 */
export function toFilterState(
  values: Record<string, unknown>,
  fields: readonly FilterFieldDescriptor[],
  previous: FilterState = {},
): FilterState {
  const owned = new Set(fields.map((f) => f.path));
  const out: FilterState = {};
  for (const [path, value] of Object.entries(previous)) {
    if (!owned.has(path)) out[path] = value;
  }

  for (const field of fields) {
    const raw = values[toName(field.path)];

    switch (field.kind) {
      case "choice": {
        const selected =
          field.single
            ? raw
              ? [String(raw)]
              : []
            : Array.isArray(raw)
              ? raw.map(String)
              : [];
        if (selected.length > 0) out[field.path] = selected;
        break;
      }
      case "number": {
        if (!Array.isArray(raw)) break;
        const lo = field.min ?? 0;
        const hi = field.max ?? 100;
        const [min, max] = raw as number[];
        // Untouched means "no constraint", not "everything".
        if (min === lo && max === hi) break;
        out[field.path] = { kind: "number", min, max };
        break;
      }
      case "date": {
        const range = (raw ?? {}) as { from?: unknown; to?: unknown };
        const from = iso(range.from);
        const to = iso(range.to);
        if (from || to) out[field.path] = { kind: "date", from, to };
        break;
      }
      case "text": {
        const text = typeof raw === "string" ? raw.trim() : "";
        if (text) out[field.path] = [text];
        break;
      }
    }
  }

  return out;
}

/**
 * Whether two filter states are the same. Used to break the `watch` → `onChange` → new `values`
 * → re-render loop that otherwise eats keystrokes: if nothing actually changed, nothing is
 * emitted.
 */
export function sameFilters(a: FilterState, b: FilterState): boolean {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (const key of keys) {
    const x = a[key];
    const y = b[key];
    if (x === undefined || y === undefined) return false;
    if (Array.isArray(x) !== Array.isArray(y)) return false;
    if (Array.isArray(x) && Array.isArray(y)) {
      if (x.length !== y.length || x.some((v, i) => v !== y[i])) return false;
    } else if (JSON.stringify(x) !== JSON.stringify(y)) {
      return false;
    }
  }
  return true;
}

/** The numeric shortcuts out of a mixed `presets` list. */
export const numberPresets = (presets?: readonly Preset[]): NumberPreset[] =>
  (presets ?? []).filter((p): p is NumberPreset => "min" in p || "max" in p);

/** The date shortcuts out of a mixed `presets` list. */
export const datePresets = (presets?: readonly Preset[]): DatePreset[] =>
  (presets ?? []).filter((p): p is DatePreset => "from" in p || "to" in p);

