/**
 * A `#1C1D1F` pill holding a list of radio rows, with hairlines between them.
 *
 * The two `:has()` rules hide the hairline above and below the row being hovered, so the hover
 * highlight reads as one continuous block instead of being sliced by a line.
 */
export function RadioGroup({
  value,
  onValueChange,
  items,
  className,
}: {
  value: string;
  onValueChange: (value: string) => void;
  items: readonly { value: string; label: string }[];
  className?: string;
}) {
  return (
    <RadioGroupPrimitive.Root
      value={value}
      onValueChange={onValueChange}
      className={cn(
        "flex flex-col space-y-0 rounded-[12px] bg-[#1C1D1F] p-1",
        "[&>div:has(>[role=radio]:hover)>.dv-divider]:opacity-0",
        "[&>div:has(>[role=radio]:hover)+div>.dv-divider]:opacity-0",
        className,
      )}
    >
      {items.map((item, i) => (
        <div key={item.value}>
          {i > 0 && <div className="dv-divider h-px bg-[#2C2D2E]" />}
          <DataViewRadio value={item.value} label={item.label} />
        </div>
      ))}
    </RadioGroupPrimitive.Root>
  );
}

// The rail. `panel.tsx` assembles the compound surface; the rest is one component per file, the
// same shape as `views/`.
export { Panel } from "./panel";

"use client";

import React, { Children, useEffect, useMemo, useRef, useState } from "react";
import { X } from "lucide-react";
import { cn } from "../../../utils/cn";
import { PanelTabsContext, useDataViewsPanel, type PanelTab } from "../context";
import { markPanel } from "../slots";
import { Columns } from "./columns";
import { SavedViews } from "./saved-views";
import { Section } from "./section";
import { Sort } from "./sort";
import { Tab, isTabElement } from "./tab";
import type { PanelProps } from "../types";

/**
 * `DataViews.Panel` — the settings rail, opened by `DataViews.PanelToggle`.
 *
 * Always dark: `data-theme="dark"` on the root makes the Buttons, Switches and Radios inside
 * resolve dark tokens against the black, even when the host app runs light. The width animates
 * from 0 so the content beside it reflows rather than being covered.
 *
 * Tabs, like views, exist because you rendered them: the strip is built from the `Panel.Tab`
 * children found here and disappears when there is only one.
 *
 * Open/closed lives on the root, because the toggle that drives it is in the header — this
 * component's sibling. Which tab is showing lives here, because nothing outside this rail cares.
 */
function PanelRoot({ children, defaultTab, title, className }: PanelProps) {
  const { open, setOpen } = useDataViewsPanel();

  // Mount at width 0, then flip to the open width on the next frame so the transition has two
  // values to animate between; on close, keep it mounted until the animation finishes.
  const [mounted, setMounted] = useState(open);
  const [expanded, setExpanded] = useState(false);
  const closeTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (open) {
      if (closeTimer.current) clearTimeout(closeTimer.current);
      setMounted(true);
      const raf = requestAnimationFrame(() => requestAnimationFrame(() => setExpanded(true)));
      return () => cancelAnimationFrame(raf);
    }
    setExpanded(false);
    closeTimer.current = setTimeout(() => setMounted(false), 300);
    return () => {
      if (closeTimer.current) clearTimeout(closeTimer.current);
    };
  }, [open]);

  const childArray = Children.toArray(children);
  const tabElements = childArray.filter(isTabElement);
  const loose = childArray.filter((n) => !isTabElement(n));

  // Keyed on the tab identities rather than the (always-new) child array — same reasoning as the
  // view registry in `data-views.tsx`.
  const tabKey = tabElements.map((el) => `${el.props.value}|${el.props.label}`).join(",");
  const tabs = useMemo<PanelTab[]>(
    () =>
      tabElements.map((el) => ({ value: el.props.value, label: el.props.label, icon: el.props.icon })),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- keyed on `tabKey`, see above
    [tabKey],
  );

  const [currentTab, setTab] = useState(defaultTab ?? "");
  const known = tabs.some((t) => t.value === currentTab);
  const fallbackTab = tabs[0]?.value ?? "";
  // A tab that stops being rendered falls back to the first, which also covers the first render
  // when no `defaultTab` was given.
  const activeTab = known ? currentTab : fallbackTab;

  const value = useMemo(() => ({ tab: activeTab, setTab, tabs }), [activeTab, setTab, tabs]);

  if (!mounted) return null;

  return (
    <PanelTabsContext.Provider value={value}>
      <div
        className={cn(
          "shrink-0 overflow-hidden transition-[width] duration-300 ease-in-out",
          expanded ? "w-[260px]" : "w-0",
        )}
      >
        <aside
          data-theme="dark"
          data-state={expanded ? "open" : "closed"}
          className={cn(
            "flex h-full w-[260px] flex-col overflow-hidden rounded-[16px] bg-black",
            "transition-opacity duration-200 ease-in-out",
            expanded ? "opacity-100" : "opacity-0",
            className,
          )}
        >
          <div className="flex items-center gap-2 px-3 py-3">
            {tabs.length > 1 ? (
              <div className="flex flex-1 items-center gap-[2px] rounded-[10px] bg-[#252729] p-[2px] shadow-[inset_0_0_5px_0_rgba(0,0,0,0.16)]">
                {tabs.map((t) => {
                  const active = t.value === activeTab;
                  return (
                    <button
                      key={t.value}
                      type="button"
                      role="tab"
                      aria-selected={active}
                      onClick={() => setTab(t.value)}
                      className={cn(
                        "flex h-6 flex-1 items-center justify-center gap-1 rounded-[8px] px-3",
                        "text-[14px] font-[510] leading-none transition-all duration-200 ease-in-out",
                        active
                          ? "bg-white text-black shadow-[0_0_10px_2px_rgba(0,0,0,0.25)]"
                          : "bg-transparent text-white hover:bg-white/5",
                      )}
                    >
                      {t.icon && (
                        <span className="flex h-[14px] w-[14px] items-center justify-center [&_svg]:h-[14px] [&_svg]:w-[14px]">
                          {t.icon}
                        </span>
                      )}
                      {t.label}
                    </button>
                  );
                })}
              </div>
            ) : (
              <span className="flex-1 text-[18px] font-[510] leading-[1.32] tracking-[-0.01em] text-white">
                {title ?? tabs[0]?.label ?? ""}
              </span>
            )}

            <button
              type="button"
              aria-label="Close settings panel"
              onClick={() => setOpen(false)}
              className="hover:bg-background-presentation-state-negative-primary flex h-7 w-7 shrink-0 items-center justify-center rounded-[8px] bg-white/[0.15] text-white transition-colors hover:text-white"
            >
              <X className="h-[18px] w-[18px]" />
            </button>
          </div>

          <div className="h-px w-full bg-[#2C2D2E]" />

          <div className="flex flex-1 flex-col gap-6 overflow-y-auto px-3 py-4">
            {tabElements}
            {loose}
          </div>
        </aside>
      </div>
    </PanelTabsContext.Provider>
  );
}


markPanel(PanelRoot);

/**
 * The rail's compound surface, assembled in one place so what it offers is readable at a glance.
 */
export const Panel = Object.assign(PanelRoot, {
  Tab,
  Section,
  Columns,
  Sort,
  SavedViews,
});

"use client";

import { useState } from "react";
import { Plus } from "lucide-react";
import { Button } from "../../Button";
import { useDataViewsFilters, useDataViewsView } from "../context";
import { RadioGroup } from "./controls";
import { Section } from "./section";
import type { PanelSavedViewsProps } from "../types";

/**
 * `DataViews.Panel.SavedViews` — pick a saved arrangement, or save the current one.
 *
 * Persistence is yours. `onSave` is handed the full snapshot — filters, sort and columns — which
 * is the part the old panel got wrong: its save callback took no arguments, so there was nothing
 * a host could actually store.
 */
export function SavedViews({
  title = "Saved View",
  views = [],
  onValueChange,
  onSave,
  saveLabel = "Save a New View",
  className,
}: PanelSavedViewsProps) {
  const { sort, setSort, columns, setColumns } = useDataViewsView();
  const { filters, setFilters } = useDataViewsFilters();
  // Which view is selected is UI state like any other — the caller stores the snapshots, not the
  // cursor into them.
  const [active, setActive] = useState("");

  /** Selecting a view is the other half of saving one: put back exactly what was stored. */
  const restore = (id: string) => {
    setActive(id);
    const snapshot = views.find((v) => v.id === id)?.snapshot;
    if (snapshot) {
      setColumns(snapshot.columns);
      setSort(snapshot.sort);
      setFilters(snapshot.filters);
    }
    onValueChange?.(id);
  };

  return (
    <Section title={title} className={className}>
      {views.length > 0 && (
        <RadioGroup
          value={active}
          onValueChange={restore}
          items={views.map((v) => ({ value: v.id, label: v.label }))}
        />
      )}
      {onSave && (
        <Button
          type="button"
          variant="BorderStyle"
          size="M"
          className="w-full"
          onClick={() => onSave({ filters, sort, columns })}
        >
          <Plus className="h-4 w-4" />
          {saveLabel}
        </Button>
      )}
    </Section>
  );
}

"use client";

import { useId, useState } from "react";
import { cn } from "../../../utils/cn";
import { ConclusionHeader } from "../../ConclusionHeader";
import type { PanelSectionProps } from "../types";

/**
 * A titled block in the rail — and, when it has a title, a **collapsible** one.
 *
 * The header is `ConclusionHeader`, the same clickable section header `FormSummary` uses for its
 * groups and the one Figma draws in this rail (`Conclusion-Header-1.0`). `Columns`, `Sort` and
 * `SavedViews` all render through here, so they all fold from one implementation.
 *
 * It colours itself from `content-presentation-global-*` tokens rather than a `text-white`
 * literal, which is what lets the same section sit in this dark rail and in the light content
 * area without a second variant.
 */
export function Section({
  title,
  description,
  collapsible = true,
  defaultOpen = true,
  children,
  className,
}: PanelSectionProps) {
  const [open, setOpen] = useState(defaultOpen);
  const bodyId = useId();
  const isCollapsible = collapsible && title != null;
  const shown = !isCollapsible || open;

  return (
    <section className={cn("flex flex-col", className)}>
      {title != null &&
        (isCollapsible ? (
          <ConclusionHeader
            label={title}
            open={open}
            onOpenChange={setOpen}
            aria-controls={bodyId}
          />
        ) : (
          // No `min-w-0` needed here, unlike the other headings: the parent is `flex flex-col`,
          // so this already stretches to the column's width rather than sizing to its text.
          <h3 className="text-content-presentation-global-primary truncate text-[18px] font-[510] leading-[1.32] tracking-[-0.01em]">
            {title}
          </h3>
        ))}

      {/* Figma groups the description with the header (a 47px block: 28px header + 18px line),
          not with the rows — so it sits outside the fold and still reads when the group is shut. */}
      {description != null && (
        <p className="typography-body-small-regular text-content-presentation-global-primary">
          {description}
        </p>
      )}

      {/* Fold/unfold: `grid-rows-[0fr → 1fr]` animates to the body's natural height without
          measuring it, so this stays a pure-CSS transition. The inner `overflow-hidden` is what
          the 0fr track actually clips — it has to stay a bare wrapper. There is no flex `gap`
          here either: a gap survives a collapsed body as dead space, so the spacing below the
          title lives on the body instead, inside what collapses. */}
      <div
        id={bodyId}
        // A collapsed body keeps its controls in the DOM, so `inert` is what takes them out of
        // the tab order and the a11y tree — `overflow-hidden` alone would still let focus in.
        inert={!shown}
        aria-hidden={!shown}
        className={cn(
          "grid transition-[grid-template-rows,opacity] duration-200 ease-in-out",
          "motion-reduce:transition-none",
          shown ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0",
        )}
      >
        <div className="overflow-hidden">
          <div className={cn("space-y-3", title != null && "pt-3")}>{children}</div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { formatPathLabel } from "../../../utils/dataViews/path";
import { useDataViewsData, useDataViewsView } from "../context";
import { RadioGroup } from "./controls";
import { Section } from "./section";
import type { PanelSortProps } from "../types";

/**
 * `DataViews.Panel.Sort` — the same intent the table headers emit, reachable from views that have
 * no headers. Picking an option writes the sort into the root's query, which leaves through
 * `onQueryChange`; nothing is reordered here, and this part takes no callback of its own.
 */
export function Sort({ title = "Default Sort", className }: PanelSortProps) {
  const { fields } = useDataViewsData();
  const { sort, setSort } = useDataViewsView();
  const sortable = fields.filter((f) => f.type !== "hidden");

  return (
    <Section title={title} className={className}>
      {sortable.length === 0 ? (
        <p className="text-content-presentation-global-tertiary text-xs">No sortable columns.</p>
      ) : (
        <RadioGroup
          value={sort?.path ?? ""}
          onValueChange={(path) =>
            // Re-picking the active field flips the direction, as clicking a header twice does.
            setSort(
              sort?.path === path && sort.direction === "asc"
                ? { path, direction: "desc" }
                : { path, direction: "asc" },
            )
          }
          items={sortable.map((field) => ({
            value: field.path,
            label: field.label ?? formatPathLabel(field.path),
          }))}
        />
      )}
    </Section>
  );
}

"use client";

import React from "react";
import { useDataViewsPanelTabs } from "../context";
import type { PanelTabProps } from "../types";

const TAB_MARKER = "__dvPanelTab";

/**
 * One tab in the panel. It renders its own children when it is the open tab and nothing when it
 * is not, so a tab is declared and filled in one place:
 *
 * ```tsx
 * <DataViews.Panel.Tab value="columns" label="Columns">
 *   <DataViews.Panel.Columns />
 * </DataViews.Panel.Tab>
 * ```
 */
export function Tab({ value, children }: PanelTabProps) {
  const { tab } = useDataViewsPanelTabs();
  if (tab !== value) return null;
  return <>{children}</>;
}
(Tab as unknown as Record<string, boolean>)[TAB_MARKER] = true;

export function isTabElement(node: React.ReactNode): node is React.ReactElement<PanelTabProps> {
  return (
    React.isValidElement(node) &&
    (node.type as unknown as Record<string, unknown>)?.[TAB_MARKER] === true
  );
}

import React from "react";

/**
 * How the root recognises its children.
 *
 * Children are the API: rendering `<DataViews.Table/>` is what makes a table view exist, and
 * rendering `<DataViews.Panel/>` is what puts a sidebar beside it. To lay those out the root has
 * to tell them apart, so each part is stamped with a marker here and found with the matching
 * guard — never `child.type === Panel`, which breaks across duplicated module instances and
 * silently stops matching after a hot reload.
 *
 * Markers and guards live in this one file rather than beside their components so that the root
 * can import all of them without importing the components themselves — otherwise `header.tsx`
 * would have to import from `data-views.tsx`, which already imports `header.tsx`.
 */

function mark<P extends object>(component: React.ComponentType<P>, key: string) {
  (component as unknown as Record<string, boolean>)[key] = true;
  return component;
}

function isMarked(node: React.ReactNode, key: string) {
  return React.isValidElement(node) && (node.type as unknown as Record<string, unknown>)?.[key] === true;
}

// ─── Views ────────────────────────────────────────────────────────────────────

/** What a view is called in the switcher when the caller does not say. */
export interface ViewMeta {
  defaultId: string;
  defaultLabel: string;
}

export function markView<P extends object>(component: React.ComponentType<P>, meta: ViewMeta) {
  (component as unknown as { __dataView: ViewMeta }).__dataView = meta;
  return component;
}

export function viewMetaOf(node: React.ReactNode): ViewMeta | undefined {
  if (!React.isValidElement(node)) return undefined;
  return (node.type as { __dataView?: ViewMeta })?.__dataView;
}

export type ViewElement = React.ReactElement<{
  id?: string;
  label?: string;
  icon?: React.ReactNode;
}>;

export function isViewElement(node: React.ReactNode): node is ViewElement {
  return viewMetaOf(node) !== undefined;
}

// ─── Everything else the root positions ───────────────────────────────────────

export const markHeader = <P extends object>(c: React.ComponentType<P>) => mark(c, "__dvHeader");
export const isHeaderElement = (n: React.ReactNode) => isMarked(n, "__dvHeader");

export const markPanel = <P extends object>(c: React.ComponentType<P>) => mark(c, "__dvPanel");
export const isPanelElement = (n: React.ReactNode) => isMarked(n, "__dvPanel");

/**
 * LOCAL PATCH (Contact Center): the empty slot — what renders *in place of* the view when a
 * settled query returns no rows. Without a marker the caller's empty state is just an "extra"
 * and stacks ABOVE the view, so an empty list shows the message on top of an empty table.
 * See `states.tsx` for why this does not reintroduce the bug upstream avoided.
 */
export const markEmpty = <P extends object>(c: React.ComponentType<P>) => mark(c, "__dvEmpty");
export const isEmptyElement = (n: React.ReactNode) => isMarked(n, "__dvEmpty");

import type { ReactNode } from "react";
import type { Themes } from "../../utils/types";
import type {
  ColumnState,
  DataViewsQuery,
  FieldConfig,
  FilterState,
  MoveIntent,
  Row,
  RowGroup,
  Sort,
  TreeNode,
} from "../../utils/dataViews/types";

/**
 * Props for every DataViews part. No runtime imports — this file is types only, as in
 * `FormBuilder/types.ts`.
 *
 * Read every `on*Change` as intent: DataViews reports what the user did and applies none of it
 * itself. The only state that leaves the component is the query — see `DataViewsRootProps`.
 */

// ─── Root ─────────────────────────────────────────────────────────────────────

export interface DataViewsRootProps {
  /** The rows to paint — already filtered, searched and sorted by you. */
  rows: readonly Row[];
  /** How to paint each field. Authored, never inferred. */
  fields: readonly FieldConfig[];
  children: ReactNode;

  /** Stable row identity (default `id ?? _id ?? uuid ?? index`). Selection and drag key off this. */
  getRowId?: (row: Row, index: number) => string;
  /**
   * How many rows match the query, before paging. Supplied by whatever ran it — the component is
   * handed one page and cannot count what it was never sent. It is what `hasMore` is derived from.
   */
  total?: number;
  /** Fetching. Each view paints skeletons in its own shape rather than emptying itself. */
  loading?: boolean;
  /**
   * Called when a view scrolls near its end. Fetch the next page and **append** it to `rows`.
   *
   * A request, not state — it deliberately does not go through `onQueryChange`, so `page` stays
   * the caller's business. With TanStack that is `fetchNextPage`, and `rows` is the flattened
   * pages. Leave it off and nothing loads on scroll.
   *
   * Whether there *is* a next page is not a prop: the component derives it from `rows.length` and
   * `total`, both of which it already has.
   */
  onLoadMore?: () => void;
  /** True while that next page is in flight. Distinct from `loading`, which is the first load. */
  loadingMore?: boolean;

  /**
   * What the user has asked for: search, filters, sort, page, page size.
   *
   * This is the only state that leaves the component, because it is the only state you can act on
   * — everything else (which view is showing, which tab is open, how the columns are arranged,
   * what is selected) changes nothing but the picture, so the component keeps it.
   *
   * Wire `onQueryChange` and go fetch. `query` itself is optional: pass it only when something
   * else genuinely owns the query, such as syncing it to the URL.
   */
  query?: DataViewsQuery;
  onQueryChange?: (query: DataViewsQuery) => void;
  /** Where the query starts. Partial — anything omitted takes its usual default. */
  defaultQuery?: Partial<DataViewsQuery>;

  /** Which view shows first. Defaults to the first one you rendered. */
  defaultView?: string;
  /** Whether the settings rail starts open. */
  defaultPanelOpen?: boolean;

  /**
   * Told, not asked. These report UI state the component owns, for the cases where an app has to
   * react to it — a bulk-action bar needs the selection, a router needs the open row. There is no
   * matching value prop: reporting is not the same as being driven.
   */
  onViewChange?: (view: string) => void;
  onSelectionChange?: (ids: readonly string[]) => void;
  onActiveIdChange?: (id: string | null) => void;

  /**
   * Applied as `data-theme`, as everywhere else in Glare. Note that the filter dropdowns and the
   * date calendar portal to `document.body`, so they follow the *page* theme rather than this one.
   */
  theme?: Themes;
  className?: string;
}

// ─── Shell ────────────────────────────────────────────────────────────────────

export interface HeaderProps {
  title?: ReactNode;
  /** `DataViews.ViewSwitch`, `.Search`, `.Actions`, `.PanelToggle` — in whatever order you like. */
  children?: ReactNode;
  className?: string;
}

export interface ViewSwitchProps {
  className?: string;
}

export interface SearchProps {
  placeholder?: string;
  className?: string;
}

export interface ActionsProps {
  children?: ReactNode;
  className?: string;
}

export interface PanelToggleProps {
  children?: ReactNode;
  className?: string;
}

// ─── Views ────────────────────────────────────────────────────────────────────

/**
 * What every view hands a render prop.
 *
 * `row` is your record, untouched. `id` is what `getRowId` resolved — the same id selection and
 * drag key off, so it is what you pass back to anything that identifies a row.
 */
export interface RowRenderArgs {
  row: Row;
  id: string;
  /** Position within the list this view is painting, not within the dataset. */
  index: number;
  /** The fields the panel left visible, in order — reuse them with `Cell` to stay consistent. */
  fields: readonly FieldConfig[];
}

/** Shared by every view: how it registers itself in the switcher. */
export interface ViewBaseProps {
  /** Switcher id. Defaults to the view's own name, so two boards need explicit ids. */
  id?: string;
  label?: string;
  icon?: ReactNode;
  className?: string;
}

export interface TableViewProps extends ViewBaseProps {
  /** Per-row checkboxes and select-all (default `false`). */
  selectable?: boolean;
  onRowClick?: (row: Row, id: string) => void;
  /**
   * Show a "+ Add New" row at the foot of the table, and what to do when it is pressed. Without
   * it there is no row — the same rule the rest of the component follows: a part exists because
   * you asked for it.
   */
  onAddRow?: () => void;
  /** The label on that row. Defaults to "Add New". */
  addRowLabel?: string;
  /**
   * Reorder rows by dragging. Passing it adds a grip column; leaving it off means no drag at all.
   *
   * Like every other drag here it emits intent and moves nothing — the row settles where it landed
   * only once you hand back reordered `rows`.
   *
   * **A manual order and a sort are two different orders**, and the component cannot reconcile
   * them: it paints whatever you give it. If a sort is active when someone drags a row, decide
   * which one wins — usually by clearing `sort` in the same update that persists the new position.
   */
  onRowMove?: (intent: MoveIntent) => void;
  /**
   * Paint one cell yourself, in this view only.
   *
   * `FieldConfig.render` is the other way to do this and usually the better one: it applies
   * wherever the field is painted, so the board's cards and the tree's labels agree with the
   * table. Reach for this when a field should look *different here* — wider, with an action, or
   * with context only the table has.
   *
   * Return `undefined` to fall through to the normal painting for that cell.
   */
  renderCell?: (args: RowRenderArgs & { field: FieldConfig }) => ReactNode;
}

export interface BoardViewProps extends ViewBaseProps {
  /** Pre-grouped columns. You build these — the board never groups rows itself. */
  groups: readonly RowGroup[];
  /** Which field to show as the card title. */
  titlePath?: string;
  /**
   * Replace the card.
   *
   * The board still owns the wrapper — dragging, the drop target, the click that opens a row —
   * and yours goes inside it, so a custom card keeps working with `onRowMove` without wiring any
   * of it yourself. `group` is the column it is sitting in.
   *
   * ```tsx
   * <DataViews.Board
   *   groups={groups}
   *   renderCard={({ row, fields, isActive }) => (
   *     <MyCard highlighted={isActive}>
   *       <Cell field={fields[0]} row={row} />
   *     </MyCard>
   *   )}
   * />
   * ```
   */
  renderCard?: (
    args: RowRenderArgs & { group: RowGroup; isActive: boolean; isDragging: boolean },
  ) => ReactNode;
  /** Drag-and-drop. Emits intent; the card does not move until you update `rows`. */
  onRowMove?: (intent: MoveIntent) => void;
  onColumnAction?: (groupId: string) => void;
}

export interface InboxViewProps extends ViewBaseProps {
  /** The detail pane. Rendered beside the list; yours to fill. */
  children?: ReactNode;
  /**
   * Replace the list item's contents. The row keeps its hover and selected treatment, its click
   * handling and its link — this fills the inside.
   */
  renderItem?: (args: RowRenderArgs & { isActive: boolean }) => ReactNode;
  /** Names the field whose label titles the list column. */
  titlePath?: string;
  /** Pulled out of the card body and shown as a pill. Defaults to the first date field. */
  datePath?: string;
  itemHref?: (row: Row, id: string) => string;
  /** Your router's Link, so selection navigates client-side. Defaults to a plain `<a>`. */
  linkComponent?: React.ElementType;
  placeholder?: ReactNode;
}

/**
 * Which shape the tree's pane lists the selected node's rows in.
 *
 * `"table"` and `"cards"` are built in; any other string is the `value` of a
 * `DataViews.Tree.PaneTab` you rendered.
 */
export type TreePaneMode = "table" | "cards" | (string & NonNullable<unknown>);

/**
 * What every tab in the tree's pane can say about itself in the switch. The two built-in views
 * fill these in — `DataViews.Tree.Table` is "List", `DataViews.Tree.Cards` is "Cards" — so you
 * pass them only to rename a tab or to register the same view twice.
 */
export interface TreePaneViewBase {
  /** What `paneMode` becomes while this tab shows. Defaults to `"table"` / `"cards"`. */
  value?: string;
  label?: string;
  icon?: ReactNode;
}

/**
 * `DataViews.Tree.Table` — the pane as a table. Everything `DataViews.Table` can do, over the
 * selected node's rows rather than the root's.
 */
export interface TreePaneTableProps
  extends TreePaneViewBase,
    Omit<TableViewProps, keyof ViewBaseProps> {}

/** `DataViews.Tree.Cards` — the pane as a grid of cards. */
export interface TreePaneCardsProps extends TreePaneViewBase {
  /** Replaces `DataViewCard` outright. Same signature as the board's `renderCard`. */
  renderCard?: (args: RowRenderArgs) => ReactNode;
  /** Replaces the grid's own classes — the responsive 1/2/3 columns and its padding. */
  className?: string;
}

/**
 * `DataViews.Tree.Tab` — a mode of your own, beside the built-in two. Its `children` are the pane
 * while it is selected and nothing while it is not.
 */
export interface TreePaneTabProps extends TreePaneViewBase {
  /** Required: there is no sensible default name for a view only you know about. */
  value: string;
  label: string;
  children?: ReactNode;
}

export interface TreeViewProps extends ViewBaseProps {
  /**
   * The pane's mode. Omit to let the view hold it.
   *
   * Seed the starting mode with `defaultPaneMode` and persist every switch from
   * `onPaneModeChange` — the same round-trip the query uses, so a reload can restore what the
   * user last chose.
   */
  paneMode?: TreePaneMode;
  /**
   * Initial mode when uncontrolled. Defaults to the **first tab you rendered** — so a pane whose
   * only tab is your own opens on it rather than on a `"table"` that matches nothing.
   */
  defaultPaneMode?: TreePaneMode;
  /** Told when the user switches. The component still owns the mode. */
  onPaneModeChange?: (mode: TreePaneMode) => void;
  /**
   * Which rows the pane lists for the selected node.
   *
   * Defaults to the node's **descendants** — a branch shows what is under it, a leaf shows
   * itself. Override it when the tree and the pane hold different things: a tree of categories
   * whose pane must list that category's items, for instance.
   */
  paneRows?: (node: TreeNode) => readonly Row[];
  /**
   * Your markup in the pane's header, between the record count and the mode switch — an
   * "Add item" button, a menu, a count of your own.
   *
   * It is a node rather than a render prop because the header is a slot, not a template: what
   * belongs there rarely varies per node, and what does can read `useActiveRow()`.
   */
  paneActions?: ReactNode;
  /** Pre-built hierarchy. You build it — the tree never derives one from the rows. */
  nodes: readonly TreeNode[];
  labelPath?: string;
  /**
   * Dress a node in the rail.
   *
   * `TreeFolder` owns the row — the indent, the connector lines, the selection band, the drag
   * grip — and takes its label as text, so this returns the three pieces it *can* vary rather
   * than arbitrary markup. `icon` sits before the name, `meta` after it.
   *
   * ```tsx
   * renderNode={({ row }) => ({
   *   icon: <Avatar size="XS" src={row.avatar as string} />,
   *   meta: <Badge label={row.status as string} color="blue" />,
   * })}
   * ```
   *
   * For markup a row cannot hold, put it in `children` — that pane is entirely yours.
   */
  renderNode?: (args: { node: TreeNode; row: Row; fields: readonly FieldConfig[] }) => {
    name?: string;
    icon?: ReactNode;
    meta?: ReactNode;
  };
  expanded?: readonly string[];
  onExpandedChange?: (ids: readonly string[]) => void;
  /** Which node is selected is `activeId` — the tree keeps no second copy. */
  onNodeMove?: (intent: MoveIntent) => void;
  /**
   * The pane's tabs: `DataViews.Tree.Table`, `DataViews.Tree.Cards`, and any
   * `DataViews.Tree.Tab` of your own. A tab exists because you rendered it, and the switch shows
   * exactly what you passed — one tab and there is no switch at all, the same rule `ViewSwitch`
   * follows. Pass **none** and there is no pane: the tree is a hierarchy and takes the whole
   * width, because a part exists here only if you rendered it.
   *
   * ```tsx
   * <DataViews.Tree nodes={nodes} labelPath="name">
   *   <DataViews.Tree.Table selectable renderCell={cell} />
   *   <DataViews.Tree.Cards renderCard={card} />
   *   <DataViews.Tree.Tab value="timeline" label="Timeline"><Timeline /></DataViews.Tree.Tab>
   * </DataViews.Tree>
   * ```
   *
   * Anything here that is **not** one of those three *is* the pane — the whole-pane override,
   * header and switch included, which is what a tree written before these tabs existed passes.
   */
  children?: ReactNode;
}

// ─── Panel ────────────────────────────────────────────────────────────────────

export interface PanelProps {
  children?: ReactNode;
  /** Which tab shows first. Defaults to the first one you rendered. */
  defaultTab?: string;
  title?: ReactNode;
  className?: string;
}

export interface PanelTabProps {
  value: string;
  label: string;
  icon?: ReactNode;
  children?: ReactNode;
}

export interface PanelSectionProps {
  /**
   * A small line under the title explaining the section — Figma's
   * "Show or hide columns in table view". Optional; most sections have none.
   *
   * It sits with the header rather than inside the fold, so it still reads when the group is shut.
   */
  description?: ReactNode;
  /** Collapsible via its `ConclusionHeader` title. Defaults to `true` when there is a title. */
  collapsible?: boolean;
  /** Initial open state when collapsible. Defaults to `true`, so nothing starts folded. */
  defaultOpen?: boolean;
  title?: ReactNode;
  children?: ReactNode;
  className?: string;
}

export interface PanelColumnsProps {
  /**
   * A small line under the title explaining the section — Figma's
   * "Show or hide columns in table view". Optional; most sections have none.
   *
   * It sits with the header rather than inside the fold, so it still reads when the group is shut.
   */
  description?: ReactNode;
  title?: ReactNode;
  /**
   * Column visibility and order — drag to reorder, toggle to hide. The component holds it: every
   * view paints from the same arrangement, so hiding a column here also retitles the board's
   * cards, and nothing outside the component can act on it.
   */
  className?: string;
}

export interface PanelSortProps {
  title?: ReactNode;
  /** The same sort the table's column headers set. Both write to the query. */
  className?: string;
}

/** What a saved view restores. Opaque to you — hand back whatever `onSave` gave you. */
export interface SavedViewSnapshot {
  filters: FilterState;
  sort: Sort;
  columns: readonly ColumnState[];
}

export interface SavedView {
  id: string;
  label: string;
  /** What `onSave` handed you. Selecting the view applies it. */
  snapshot?: SavedViewSnapshot;
}

export interface PanelSavedViewsProps {
  title?: ReactNode;
  views?: readonly SavedView[];
  /** Told which view was picked, after it has been applied. */
  onValueChange?: (id: string) => void;
  /**
   * Called with everything needed to persist a view. Store it against an id and hand it back in
   * `views` — selecting it puts the filters, sort and columns back.
   */
  onSave?: (snapshot: SavedViewSnapshot) => void;
  saveLabel?: ReactNode;
  className?: string;
}

// ─── Filters ──────────────────────────────────────────────────────────────────

export interface FiltersProps {
  /**
   * A small line under the title explaining the section — Figma's
   * "Show or hide columns in table view". Optional; most sections have none.
   *
   * It sits with the header rather than inside the fold, so it still reads when the group is shut.
   */
  description?: ReactNode;
  /** Collapsible via its `ConclusionHeader` title. Defaults to `true` when there is a title. */
  collapsible?: boolean;
  /** Initial open state when collapsible. Defaults to `true`, so nothing starts folded. */
  defaultOpen?: boolean;
  /**
   * The controls, as `FormBuilder` fields — one JSX child per filter, exactly as a form is
   * written. `Filters` reads each child's `name`, `label` and bounds to learn what it is:
   *
   * ```tsx
   * <DataViews.Filters>
   *   <FormBuilder.MultiSelect name="status" label="Status" options={STATUS} />
   *   <FormBuilder.Slider name="total" label="Total" range min={0} max={15000} />
   * </DataViews.Filters>
   * ```
   *
   * Fields whose value has no filter meaning — `Checkbox`, `File`, `Custom` — are rendered but not
   * collected; use `Filters.Custom` for a control of your own.
   */
  children?: ReactNode;
  title?: ReactNode;
  clearLabel?: ReactNode;
  className?: string;
}

export interface FilterControlProps {
  path: string;
  label?: ReactNode;
}

/**
 * `DataViews.Filters.Presets` — one-click shortcuts for a slider or a date range, which
 * FormBuilder has no field for.
 *
 * ```tsx
 * <FormBuilder.Slider name="total" label="Total" range min={0} max={15000} />
 * <DataViews.Filters.Presets for="total" items={[{ label: "Under $500", max: 500 }]} />
 * ```
 */
export interface FilterPresetsProps {
  /** The `name` of the field these apply to. */
  for: string;
  items: readonly import("../../utils/dataViews/types").Preset[];
  className?: string;
}

export interface FilterCustomProps extends FilterControlProps {
  /** The escape hatch — render any control against this filter's value. */
  render: (args: {
    value: import("../../utils/dataViews/types").FilterValue | undefined;
    setValue: (v: import("../../utils/dataViews/types").FilterValue | undefined) => void;
  }) => ReactNode;
}

