"use client";

import React, { useMemo } from "react";
import { MoreHorizontal } from "lucide-react";
import { cn } from "../../../utils/cn";
import type { ColumnColor, RowGroup } from "../../../utils/dataViews/types";
import { Button } from "../../Button";
import { DataViewCard } from "../../../layouts/DataViewCard";
import {
  DragGhost,
  DragList,
  useDragDrop,
  useDragItem,
  useDropContainer,
} from "../../../hooks/useDragDrop";
import { Cell } from "../cell";
import { SkeletonBar, skeletonKeys } from "../states";
import { buildCardRows } from "./card-rows";
import { useInfiniteScroll } from "../../../hooks/useInfiniteScroll";
import { useDataViewsData, useDataViewsView } from "../context";
import { markView } from "../slots";
import type { BoardViewProps } from "../types";

/**
 * The Figma column pills are deeply saturated dark fills (#131415, #330C69, #532200, #002F66).
 * Each is matched to the closest raw-colour token; purple has no close presentation-layer match,
 * so it stays the exact Figma hex.
 */
const COLUMN_BG: Record<ColumnColor, string> = {
  gray: "bg-black-900",
  purple: "bg-[#330C69]",
  orange: "bg-orange-900",
  blue: "bg-blue-sparkle-900",
  green: "bg-green-cyan-900",
  red: "bg-red-orange-900",
};

/**
 * `DataViews.Board` — a kanban board.
 *
 * You hand it `groups`; it never groups rows itself. That is deliberate: grouping is a query, and
 * which statuses exist (including the empty ones you still want a column for) is knowledge the
 * board does not have.
 *
 * Dragging emits `onRowMove` and **does not move the card**. The card moves when you update
 * `rows`/`groups` in response — so a failed save leaves the board showing the truth instead of a
 * lie. If nothing seems to happen on drop, that round-trip is what is missing.
 */
function BoardViewImpl({
  groups,
  titlePath,
  renderCard,
  onRowMove,
  onColumnAction,
  className,
}: BoardViewProps) {
  const { visibleFields, getRowId, loading } = useDataViewsData();
  const { activeId, setActiveId } = useDataViewsView();

  const titleField = titlePath ? visibleFields.find((f) => f.path === titlePath) : visibleFields[0];
  const bodyFields = visibleFields.filter((f) => f.path !== titleField?.path);

  /**
   * Where every card currently sits. A drop reports only what it landed *on* — which may be a
   * column or another card — so this is what turns that into "which column, at what index".
   */
  const placement = useMemo(() => {
    const map = new Map<string, { group: string; index: number }>();
    for (const group of groups) {
      group.rows.forEach((row, index) => {
        map.set(getRowId(row, index), { group: group.id, index });
      });
    }
    return map;
  }, [groups, getRowId]);

  const { DndContext, contextProps, activeId: draggingId, overId } = useDragDrop({
    mode: "board",
    disabled: !onRowMove,
    containerOf: (id) => placement.get(id)?.group ?? null,
    onMove: ({ id, from, to }) => {
      if (!to) return;
      // Dropped on a card: take that card's column and slot in at its position. Dropped on the
      // column itself — which is what an empty column offers — append.
      const onCard = placement.get(to);
      onRowMove?.({
        id,
        from,
        to: onCard ? onCard.group : to,
        ...(onCard ? { index: onCard.index } : null),
      });
    },
  });

  /**
   * Which column the drop would land in. Not `useDropContainer`'s `isOver`: the nearest droppable
   * to the pointer is almost always a *card*, so a column with anything in it would never light
   * up. The card's own column is the answer.
   */
  const targetGroup = overId ? (placement.get(overId)?.group ?? overId) : null;

  /** The row under the pointer, so the ghost can be the card itself rather than an outline. */
  const dragging = draggingId
    ? groups
        .flatMap((group) =>
          group.rows.map((row, index) => ({ row, group, index, id: getRowId(row, index) })),
        )
        .find((r) => r.id === draggingId)
    : undefined;

  return (
    <DndContext {...contextProps}>
      <div
        className={cn(
          "bg-background-presentation-body-primary h-full overflow-x-auto p-2",
          className,
        )}
      >
        <div className="flex h-full gap-4" style={{ minWidth: "max-content" }}>
        {groups.map((group, i) => (
          <React.Fragment key={group.id}>
            <BoardColumn
              group={group}
              isTarget={targetGroup === group.id}
              onColumnAction={onColumnAction}
              ids={group.rows.map((row, index) => getRowId(row, index))}
            >
              {loading && <SkeletonCards />}
              {!loading && group.rows.map((row, index) => {
                // `index` is the position within this column. It only reaches `getRowId` as the
                // last-resort fallback for rows with no id of their own — give those a stable
                // `getRowId` if you drag them, or two columns will hand out the same key.
                const id = getRowId(row, index);
                return (
                  <BoardCard
                    key={id}
                    id={id}
                    draggable={Boolean(onRowMove)}
                    isActive={activeId === id}
                    onClick={() => setActiveId(activeId === id ? null : id)}
                  >
                    {(isDragging) =>
                      renderCard ? (
                        renderCard({
                          row,
                          id,
                          index,
                          fields: visibleFields,
                          group,
                          isActive: activeId === id,
                          isDragging,
                        })
                      ) : (
                        <DataViewCard
                          title={titleField ? <Cell field={titleField} row={row} /> : undefined}
                          rows={buildCardRows(bodyFields, row)}
                          className={cn(
                            onRowMove
                              ? "cursor-grab transition-shadow hover:shadow-md active:cursor-grabbing"
                              : "cursor-pointer",
                            activeId === id && "border-border-presentation-state-focus",
                          )}
                        />
                      )
                    }
                  </BoardCard>
                );
              })}
            </BoardColumn>

            {i < groups.length - 1 && (
              // Starts below the column header rather than at the top of the board.
              <div
                aria-hidden
                className="border-border-presentation-global-primary mt-[42px] self-stretch border-l-[2px] border-dashed"
              />
            )}
          </React.Fragment>
          ))}
        </div>
      </div>

      {/* The ghost is the card, drawn through whatever renders the real one — a custom
          `renderCard` included, or the ghost would announce itself as a different object. */}
      <DragGhost>
        {dragging && (
          <div className="w-[271px] cursor-grabbing opacity-95 shadow-lg">
            {renderCard ? (
              renderCard({
                row: dragging.row,
                id: dragging.id,
                index: dragging.index,
                fields: visibleFields,
                group: dragging.group,
                isActive: activeId === dragging.id,
                isDragging: true,
              })
            ) : (
              <DataViewCard
                title={titleField ? <Cell field={titleField} row={dragging.row} /> : undefined}
                rows={buildCardRows(bodyFields, dragging.row)}
                className="border-border-presentation-state-focus"
              />
            )}
          </div>
        )}
      </DragGhost>
    </DndContext>
  );
}

/**
 * Asks for the next page when *this* column is scrolled to its end.
 *
 * Every column calls the same `onLoadMore`, because the board is fed one shared page of rows and
 * regroups them — so a short column can end up asking for more on behalf of a long one. That is
 * the trade for not having to page each column separately.
 */
function ColumnSentinel() {
  const { loading, loadingMore, hasMore, onLoadMore } = useDataViewsData();
  const { sentinelRef } = useInfiniteScroll({
    onLoadMore,
    hasMore,
    loading: loading || loadingMore,
  });
  if (!hasMore || loading) return null;
  return (
    <>
      <div ref={sentinelRef as React.Ref<HTMLDivElement>} aria-hidden className="h-px shrink-0" />
      {loadingMore && <SkeletonCards count={1} />}
    </>
  );
}

/** Per column. Two is enough to read as "cards are coming" without pretending to know how many. */
const SKELETON_CARDS = 2;

/**
 * The loading column.
 *
 * A real `DataViewCard` with shimmer where its text goes, so the card's radius, border and padding
 * are the ones the data will land in. The column header above keeps its label and colour — only
 * the cards are unknown.
 */
function SkeletonCards({ count = SKELETON_CARDS }: { count?: number }) {
  return (
    <>
      {skeletonKeys(count).map((i) => (
        <DataViewCard
          key={`skeleton-${i}`}
          title={<SkeletonBar className="h-[18px] w-[60%]" />}
          rows={[
            [
              { key: "a", label: <SkeletonBar className="w-[54px]" />, value: <SkeletonBar className="w-[64px]" /> },
              { key: "b", label: <SkeletonBar className="w-[44px]" />, value: <SkeletonBar className="w-[72px]" /> },
            ],
          ]}
        />
      ))}
    </>
  );
}

/**
 * A column: a drop target in its own right, so a card can be dropped on an empty one.
 *
 * `DragList` is what lets a card be dropped *between* two others rather than only onto the column.
 */
function BoardColumn({
  group,
  ids,
  isTarget,
  onColumnAction,
  children,
}: {
  group: RowGroup;
  ids: string[];
  isTarget: boolean;
  onColumnAction?: (groupId: string) => void;
  children: React.ReactNode;
}) {
  const { ref, isOver, containerProps } = useDropContainer(group.id);

  return (
    <div
      ref={ref}
      {...containerProps}
      className={cn(
        // The transparent 2px border is permanent so the drop-target state costs no layout shift.
        "flex w-[279px] flex-col gap-2 rounded-[12px] border-2 border-transparent p-1",
        "transition-colors duration-150 ease-in-out",
        (isOver || isTarget) &&
          "bg-background-presentation-cardbutton-blue-hover border-border-presentation-state-focus border-dashed",
      )}
    >
      <ColumnHeader group={group} onAction={onColumnAction} />
      <div className="flex flex-col gap-2 overflow-y-auto py-1">
        <DragList ids={ids}>{children}</DragList>
        <ColumnSentinel />
      </div>
    </div>
  );
}

/**
 * The wrapper around a card — ours whichever card is shown, because dragging and the click that
 * opens a row are board behaviour, not card decoration.
 *
 * `children` is a function so a custom card can be told whether it is the one being dragged
 * without this component knowing what it renders.
 */
function BoardCard({
  id,
  draggable,
  isActive,
  onClick,
  children,
}: {
  id: string;
  draggable: boolean;
  isActive: boolean;
  onClick: () => void;
  children: (isDragging: boolean) => React.ReactNode;
}) {
  const { ref, handleProps, style, isDragging } = useDragItem(id, !draggable);

  return (
    <div
      ref={ref}
      style={style}
      {...handleProps}
      onClick={onClick}
      data-active={isActive || undefined}
      className={cn(
        draggable ? "cursor-grab active:cursor-grabbing" : "cursor-pointer",
        isDragging && "opacity-40",
      )}
    >
      {children(isDragging)}
    </div>
  );
}

/** The solid dark pill at the top of a column. No dot, no count — just the title and an action. */
function ColumnHeader({
  group,
  onAction,
}: {
  group: RowGroup;
  onAction?: (groupId: string) => void;
}) {
  return (
    <div
      className={cn(
        "flex items-center justify-between rounded-[8px] px-[6px] py-[4px]",
        COLUMN_BG[group.color ?? "gray"],
      )}
    >
      {/* `min-w-0` because this is a flex item: without it the heading refuses to shrink below its
          text and a long group name pushes the action button out of the column. */}
      <h3 className="typography-headers-small-medium text-content-presentation-global-primary-light min-w-0 truncate">
        {group.label}
      </h3>
      {onAction && (
        <Button
          variant="BorderStyle"
          buttonType="icon"
          className="text-content-presentation-global-primary-light h-5 w-5 border-0 bg-transparent hover:bg-white/10"
          onClick={() => onAction(group.id)}
        >
          <MoreHorizontal className="h-3.5 w-3.5" />
        </Button>
      )}
    </div>
  );
}

export const BoardView = markView(BoardViewImpl, {
  defaultId: "board",
  defaultLabel: "Board",
});

"use client";

import { getByPath } from "../../../utils/dataViews/path";
import type { FieldConfig, Row } from "../../../utils/dataViews/types";
import type { DataViewCardRow } from "../../../layouts/DataViewCard";
import { Cell } from "../cell";

/**
 * Turn a row's fields into the `DataViewCard` body.
 *
 * Shared by the board's cards and the tree pane's, so the same row looks the same in both rather
 * than drifting into two nearly-identical builders.
 *
 * Pair the body fields two per row so the card grid keeps its rhythm even when one side is
 * missing: a lone survivor spans both columns, and fully empty pairs are dropped rather than
 * rendering a phantom row of hairlines.
 */
export function buildCardRows(fields: readonly FieldConfig[], row: Row): DataViewCardRow[] {
  const rows: DataViewCardRow[] = [];
  for (let i = 0; i < fields.length; i += 2) {
    const pair = [fields[i], fields[i + 1]];
    const cells: DataViewCardRow = [];
    for (const [offset, field] of pair.entries()) {
      if (!field) continue;
      if (getByPath(row, field.path) == null) continue;
      cells.push({
        // Position, not path — two fields may share one.
        key: `${field.path}-${i + offset}`,
        label: field.label ?? field.path,
        value: <Cell field={field} row={row} />,
      });
    }
    if (cells.length > 0) rows.push(cells);
  }
  return rows;
}

"use client";

import React from "react";
import { cn } from "../../../utils/cn";
import type { FieldConfig } from "../../../utils/dataViews/types";
import { Divider } from "../../Divider";
import { Cell } from "../cell";
import { SkeletonBar, skeletonKeys } from "../states";
import { useInfiniteScroll } from "../../../hooks/useInfiniteScroll";
import { useDataViewsData, useDataViewsView } from "../context";
import { useActiveRow } from "../hooks/useActiveRow";
import { markView } from "../slots";
import type { InboxViewProps } from "../types";

/**
 * `DataViews.Inbox` — a list of record cards on the left, the one you picked on the right.
 *
 * The rows are not mail-style title/preview lines: each card is a stack of `label : value` rows
 * with a date pill in the corner, so an inbox of orders reads as orders rather than as email.
 *
 * The right pane is `children`: the inbox knows which row is active (`activeId`) but not how you
 * want it displayed, so it hands the decision back rather than inventing a detail layout.
 */
function InboxViewImpl({
  children,
  renderItem,
  titlePath,
  datePath,
  itemHref,
  linkComponent,
  placeholder,
  className,
}: InboxViewProps) {
  const { rows, visibleFields, getRowId, loading, loadingMore, hasMore, onLoadMore } =
    useDataViewsData();
  const { sentinelRef } = useInfiniteScroll({
    onLoadMore,
    hasMore,
    loading: loading || loadingMore,
  });
  const { activeId, setActiveId } = useDataViewsView();
  // "Is a row open?", not "is an id set?". `activeId` is shared with the other views, so it can
  // outlive the row it named — after a refetch, or after the tree selected a grouping node that
  // is not a row at all. Keying off the row keeps the pane and the placeholder consistent.
  const activeRow = useActiveRow();

  const byPath = (path: string | undefined) =>
    path ? visibleFields.find((f) => f.path === path) : undefined;

  // The date is pulled out of the card body and shown as a pill; everything else becomes a
  // label/value row.
  const dateField = byPath(datePath) ?? visibleFields.find((f) => f.type === "date" || f.type === "date-format");
  const titleField = byPath(titlePath);
  const rowFields = visibleFields.filter(
    (f) => f.path !== dateField?.path && f.type !== "hidden",
  );

  const Link = linkComponent ?? "a";

  return (
    // Split, like the tree: the gap shows the shell's black and the two panels sit on it.
    <div className={cn("flex h-full flex-col gap-2 bg-black md:flex-row", className)}>
      <ul
        className={cn(
          "border-border-presentation-global-primary flex w-full flex-col overflow-hidden rounded-[16px] border",
          "bg-background-presentation-form-base md:w-96",
        )}
      >
        <li className="border-border-presentation-global-primary border-b px-3 py-2">
          {/* `block` before `truncate`: the parent is a plain `<li>`, so this span would otherwise
              be inline — and `overflow` has no effect on an inline box, which would leave the
              ellipsis silently doing nothing. */}
          <span
            style={{ fontFeatureSettings: "'cv05' on" }}
            className="typography-display-medium-medium text-content-presentation-global-primary block truncate uppercase"
          >
            {titleField?.label ?? "inbox"}
          </span>
        </li>

        <div className="bg-background-presentation-button-disabled flex flex-1 flex-col gap-1 overflow-y-auto py-1">
          {loading && <SkeletonItems count={rowFields.length || 2} />}
          {!loading && rows.map((row, index) => {
            const id = getRowId(row, index);
            const selected = activeId === id;
            const href = itemHref?.(row, id);

            const card = renderItem ? (
              renderItem({ row, id, index, fields: visibleFields, isActive: selected })
            ) : (
              <>
                <div className="flex w-full flex-col gap-1">
                  {rowFields.map((field, i) => (
                    <div key={`${field.path}-${i}`} className="flex flex-col">
                      <div className="flex items-center gap-2">
                        <span className="typography-body-large-semibold text-content-presentation-global-secondary w-[100px] shrink-0">
                          {field.label ?? field.path}:
                        </span>
                        <span className="flex h-full items-center py-0.5">
                          <span className="bg-black-alpha-15 block h-full w-px" />
                        </span>
                        <span className="typography-body-large-medium text-content-presentation-global-primary min-w-0 flex-1 truncate">
                          <Cell field={field} row={row} />
                        </span>
                      </div>
                      {i < rowFields.length - 1 && <Divider className="mt-1" />}
                    </div>
                  ))}
                </div>

                {dateField && (
                  <div className="flex items-center justify-end">
                    <div className="bg-black-alpha-10 inline-flex items-center gap-0.5 rounded-md p-0.5">
                      <div className="rounded-sm px-1">
                        <span className="typography-labels-medium-semibold text-content-presentation-global-primary">
                          {dateField.label ?? "Created at"}:
                        </span>
                      </div>
                      <div className="bg-black-alpha-075 rounded-sm px-1">
                        <span className="typography-labels-medium-semibold text-content-presentation-global-primary">
                          <Cell field={dateField} row={row} />
                        </span>
                      </div>
                    </div>
                  </div>
                )}
              </>
            );

            const cardClass = cn(
              "flex cursor-pointer flex-col gap-2 p-3 transition-colors",
              "bg-background-presentation-form-base",
              // The transparent 2px edges are permanent so hover and selection never shift the row.
              "border-y-2 border-transparent",
              !selected &&
                "hover:bg-[image:linear-gradient(0deg,rgba(151,72,255,0.05)_0%,rgba(151,72,255,0.05)_100%)] hover:border-y-[#AE71FF]",
              selected &&
                "bg-[image:linear-gradient(0deg,rgba(0,117,255,0.05)_0%,rgba(0,117,255,0.05)_100%)] border-y-border-presentation-state-focus",
            );

            return (
              <li key={id}>
                {href ? (
                  <Link
                    href={href}
                    onClick={() => setActiveId(id)}
                    className={cn(cardClass, "text-inherit no-underline")}
                  >
                    {card}
                  </Link>
                ) : (
                  <div
                    role="button"
                    tabIndex={0}
                    aria-current={selected || undefined}
                    onClick={() => setActiveId(id)}
                    onKeyDown={(e) => {
                      if (e.key !== "Enter" && e.key !== " ") return;
                      e.preventDefault();
                      setActiveId(id);
                    }}
                    className={cardClass}
                  >
                    {card}
                  </div>
                )}
              </li>
            );
          })}
          {/* Asks for the next page as the list nears its end. Inside the scroller, so it is the
              list's own scrolling that triggers it. */}
          {hasMore && !loading && (
            <li ref={sentinelRef as React.Ref<HTMLLIElement>} aria-hidden className="h-px" />
          )}
          {loadingMore && <SkeletonItems count={rowFields.length || 2} items={2} />}
        </div>
      </ul>

      <div
        className={cn(
          "bg-background-presentation-form-base flex flex-1 flex-col overflow-hidden rounded-[16px]",
          activeRow === null && "border-border-presentation-global-primary items-center justify-center border",
        )}
      >
        {activeRow === null
          ? (placeholder ?? (
              <p className="text-content-presentation-global-tertiary">
                Select an item to view details
              </p>
            ))
          : children}
      </div>
    </div>
  );
}

/** Enough items to fill the list's fold. */
const SKELETON_ITEMS = 5;

/**
 * The loading list.
 *
 * Mirrors a real item: the same `p-3` card with `border-y-2` transparent edges, and the same
 * label / divider / value row at the 100px label column — so items do not reflow when the messages
 * arrive. `count` is the number of field rows a real item will have.
 */
function SkeletonItems({ count, items = SKELETON_ITEMS }: { count: number; items?: number }) {
  return (
    <>
      {skeletonKeys(items).map((item) => (
        <li key={`skeleton-${item}`}>
          <div className="bg-background-presentation-form-base flex flex-col gap-2 border-y-2 border-transparent p-3">
            <div className="flex w-full flex-col gap-1">
              {skeletonKeys(count).map((i) => (
                <div key={i} className="flex items-center gap-2">
                  <SkeletonBar className="w-[100px] shrink-0" />
                  <span className="flex h-full items-center py-0.5">
                    <span className="bg-black-alpha-15 block h-full w-px" />
                  </span>
                  <SkeletonBar className={["w-[60%]", "w-[40%]", "w-[75%]"][(item + i) % 3]} />
                </div>
              ))}
            </div>
          </div>
        </li>
      ))}
    </>
  );
}

/**
 * `DataViews.Detail` — the default detail pane: every visible field as a label/value row. Drop it
 * in when you want something reasonable immediately, and replace it with your own JSX when you
 * do not.
 */
export function Detail({ className }: { className?: string }) {
  const { visibleFields } = useDataViewsData();
  const row = useActiveRow();
  if (!row) return null;

  return (
    <dl className={cn("flex flex-col gap-3 p-6", className)}>
      {visibleFields.map((f: FieldConfig, i) => (
        <div key={`${f.path}-${i}`} className="flex flex-col gap-[2px]">
          <dt className="typography-body-small-regular text-content-presentation-global-tertiary">
            {f.label ?? f.path}
          </dt>
          <dd className="typography-body-medium-medium text-content-presentation-global-primary">
            <Cell field={f} row={row} />
          </dd>
        </div>
      ))}
    </dl>
  );
}

export const InboxView = markView(InboxViewImpl, {
  defaultId: "inbox",
  defaultLabel: "Inbox",
});

"use client";

import React, { createContext, useContext } from "react";
import { LayoutGrid, Table2 } from "lucide-react";
import { DataViewCard } from "../../../layouts/DataViewCard";
import type { FieldConfig } from "../../../utils/dataViews/types";
import { useDataViewsData } from "../context";
import { Cell } from "../cell";
import { buildCardRows } from "./card-rows";
import { TableView } from "./table-view";
import type {
  TreePaneCardsProps,
  TreePaneTabProps,
  TreePaneTableProps,
  TreePaneViewBase,
} from "../types";

/**
 * The tree pane's own views, written the way every other part of this component is: **you render
 * them, and that is what makes them exist**.
 *
 * ```tsx
 * <DataViews.Tree nodes={nodes} labelPath="name">
 *   <DataViews.Tree.Table selectable renderCell={cell} />
 *   <DataViews.Tree.Cards renderCard={card} />
 *   <DataViews.Tree.Tab value="timeline" label="Timeline" icon={<Clock />}>
 *     <Timeline />
 *   </DataViews.Tree.Tab>
 * </DataViews.Tree>
 * ```
 *
 * Render one and the switch disappears, exactly as the header's `ViewSwitch` does with a single
 * view — a switch with one option is a label. Render none and there is no pane at all: the tree
 * is then a hierarchy and nothing else, and it takes the whole width.
 *
 * All three sit inside the pane's data scope, so `useDataViewsData()` in any of them returns the
 * **selected node's** rows rather than the whole set.
 */

const PANE_VIEW = "__dvTreePaneView";

interface PaneViewMeta {
  defaultValue: string;
  defaultLabel: string;
  defaultIcon?: React.ReactNode;
}

/**
 * The tab's own props, stripped off before the rest reaches the view underneath.
 *
 * `label` and `icon` name the *tab*; `DataViews.Table` reads the same two to name itself in the
 * root's switcher, so leaving them on would register the pane's table up in the header.
 */
function withoutTabProps<T extends TreePaneViewBase>(props: T) {
  const rest = { ...props };
  delete rest.value;
  delete rest.label;
  delete rest.icon;
  return rest;
}

interface PaneContextValue {
  mode: string;
  /** Which field labels a row — the tree's `labelPath`, already resolved. */
  labelField?: FieldConfig;
}

const PaneContext = createContext<PaneContextValue>({ mode: "table" });

export const TreePaneProvider = PaneContext.Provider;

function markPaneView<P extends object>(component: React.ComponentType<P>, meta: PaneViewMeta) {
  (component as unknown as Record<string, PaneViewMeta>)[PANE_VIEW] = meta;
  return component;
}

export type PaneViewElement = React.ReactElement<{
  value?: string;
  label?: string;
  icon?: React.ReactNode;
}>;

export function paneViewMetaOf(node: React.ReactNode): PaneViewMeta | undefined {
  if (!React.isValidElement(node)) return undefined;
  return (node.type as unknown as Record<string, PaneViewMeta | undefined>)[PANE_VIEW];
}

export function isPaneViewElement(node: React.ReactNode): node is PaneViewElement {
  return paneViewMetaOf(node) !== undefined;
}

/**
 * Children, with fragments opened out.
 *
 * `React.Children.toArray` stops at a `<>…</>`, so tabs grouped in one — which is what writing
 * them behind a condition produces — would arrive as a single unrecognised child and be read as a
 * whole-pane override. Flattening first is what lets `{cond ? <><Table/><Cards/></> : <Mine/>}`
 * mean what it looks like.
 */
export function flattenChildren(children: React.ReactNode): React.ReactNode[] {
  return React.Children.toArray(children).flatMap((child) =>
    React.isValidElement(child) && child.type === React.Fragment
      ? flattenChildren((child.props as { children?: React.ReactNode }).children)
      : [child],
  );
}

/** `value`, `label` and `icon` as the switch will show them — defaults filled in. */
export function paneViewOption(element: PaneViewElement) {
  const meta = paneViewMetaOf(element)!;
  return {
    value: element.props.value ?? meta.defaultValue,
    label: element.props.label ?? meta.defaultLabel,
    icon: element.props.icon ?? meta.defaultIcon,
  };
}

/** True while this element is the pane's selected mode. */
function useIsActive(element: { value?: string }, defaultValue: string) {
  const { mode } = useContext(PaneContext);
  return mode === (element.value ?? defaultValue);
}

// ─── The three ────────────────────────────────────────────────────────────────

/**
 * The pane as a table — the **real `DataViews.Table`**, not a copy, so it keeps sortable headers,
 * selection, `renderCell`, the drag grip, `+ Add New` and virtualization past 300 rows. It reads
 * its rows from the pane's scope, which is what points it at the selected node.
 *
 * One consequence worth knowing: its headers sort by writing to the **query**, which is how the
 * root fetches. Sort the pane's rows in `paneRows` if you want the order self-contained.
 */
export const PaneTable = markPaneView(function PaneTable(props: TreePaneTableProps) {
  const active = useIsActive({ value: props.value }, "table");
  if (!active) return null;
  // Standalone, `TableView` draws its own border and radius so it reads as a separated surface.
  // In here it is not standalone: the pane around it already draws exactly that border and radius
  // (`tree-view.tsx`), so leaving the table's on nests one inside the other a pixel apart.
  // `TreePaneTableProps` omits `className`, so there is no caller value to merge with.
  return <TableView {...withoutTabProps(props)} className="rounded-none border-0" />;
}, { defaultValue: "table", defaultLabel: "List", defaultIcon: <Table2 /> });

/**
 * The pane as cards — the same `DataViewCard` the board paints, so a row looks the same in both.
 * `renderCard` replaces it outright with markup of your own.
 */
export const PaneCards = markPaneView(function PaneCards({
  value,
  renderCard,
  className,
}: TreePaneCardsProps) {
  const { labelField } = useContext(PaneContext);
  const { rows, visibleFields, getRowId } = useDataViewsData();
  const active = useIsActive({ value }, "cards");
  if (!active) return null;

  return (
    <div
      className={
        className ??
        "grid grid-cols-1 content-start gap-3 p-4 sm:grid-cols-2 lg:grid-cols-3"
      }
    >
      {rows.map((row, index) => {
        const id = getRowId(row, index);
        return (
          <React.Fragment key={id}>
            {renderCard ? (
              renderCard({ row, id, index, fields: visibleFields })
            ) : (
              <DataViewCard
                title={labelField ? <Cell field={labelField} row={row} /> : undefined}
                rows={buildCardRows(
                  visibleFields.filter((f) => f.path !== labelField?.path),
                  row,
                )}
              />
            )}
          </React.Fragment>
        );
      })}
    </div>
  );
}, { defaultValue: "cards", defaultLabel: "Cards", defaultIcon: <LayoutGrid /> });

/**
 * A mode of your own. Unlike the two above it has no default content — its `children` are the
 * pane while it is selected, and nothing while it is not.
 *
 * `value` is required here: there is no sensible default name for a view only you know about.
 */
export const PaneTab = markPaneView(function PaneTab({ value, children }: TreePaneTabProps) {
  if (!useIsActive({ value }, value)) return null;
  return <>{children}</>;
}, { defaultValue: "", defaultLabel: "Tab" });

"use client";

import React from "react";
import { Plus } from "lucide-react";
import { useVirtualizer } from "@tanstack/react-virtual";
import { cn } from "../../../utils/cn";
import { formatPathLabel } from "../../../utils/dataViews/path";
import type { Sort } from "../../../utils/dataViews/types";
import { Checkbox } from "../../Checkbox";
import {
  Table,
  TableBody,
  TableCell,
  TableEndAction,
  TableHead,
  TableHeader,
  TableRow,
} from "../../Table";
import { DragList, useDragDrop, useDragItem } from "../../../hooks/useDragDrop";
import { Cell } from "../cell";
import { SkeletonBar, skeletonKeys } from "../states";
import { useInfiniteScroll } from "../../../hooks/useInfiniteScroll";
import { useDataViewsData, useDataViewsView } from "../context";
import { markView } from "../slots";
import type { TableViewProps } from "../types";

/**
 * `DataViews.Table` — rows and columns.
 *
 * Built on the shared `Table` component rather than a bare `<table>`, which is where the 44px
 * header band, the 50px rows, the cell grid, the right-edge fade and the drag-resize handles all
 * come from. Rebuilding those by hand is how this view drifts away from every other table in the
 * product.
 *
 * Columns come from `visibleFields`, which the root resolved once from `fields` + `columns`. The
 * header cells are sort *buttons*: clicking one puts a `sort` in the query and nothing else. The table
 * paints `rows` in the order you handed them over, always — if the arrow points down and the rows
 * are not descending, that is your query's business, not the table's.
 */
function TableViewImpl({
  selectable = false,
  onRowClick,
  onRowMove,
  onAddRow,
  addRowLabel = "Add New",
  renderCell,
  className,
}: TableViewProps) {
  const { rows, visibleFields, getRowId, loading, loadingMore, hasMore, onLoadMore } =
    useDataViewsData();
  const { sort, setSort, selection, setSelection } = useDataViewsView();

  const ids = rows.map((row, i) => getRowId(row, i));

  const { DndContext, contextProps, activeId: activeDragId } = useDragDrop({
    mode: "list",
    disabled: !onRowMove,
    onMove: ({ id, to }) => {
      const index = ids.indexOf(String(to));
      if (index < 0) return;
      onRowMove?.({ id, from: null, to: null, index });
    },
  });
  const allSelected = ids.length > 0 && ids.every((id) => selection.includes(id));
  const someSelected = !allSelected && ids.some((id) => selection.includes(id));

  const toggleRow = (id: string) =>
    setSelection(selection.includes(id) ? selection.filter((s) => s !== id) : [...selection, id]);

  const toggleAll = () => setSelection(allSelected ? [] : ids);

  // asc → desc → unsorted, so a third click gets you back to the server's natural order.
  const cycle = (path: string): Sort => {
    if (sort?.path !== path) return { path, direction: "asc" };
    return sort.direction === "asc" ? { path, direction: "desc" } : null;
  };

  // ── Virtualization ────────────────────────────────────────────────────────
  //
  // A mode the table *enters*, not how it always renders. Below the threshold this whole block is
  // inert and the markup below is exactly what it has always been — which is what keeps the row
  // drag, the column resize and every existing example untouched.
  const scrollRef = React.useRef<HTMLDivElement | null>(null);
  const tableRef = React.useRef<HTMLTableElement | null>(null);
  const virtualize = rows.length > VIRTUALIZE_AFTER;

  const virtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => scrollRef.current,
    // Exact, not an estimate: rows are 40px by design (Figma's `Table-RowBackgroand-1.1`), so
    // there is nothing to measure and no correction pass.
    estimateSize: () => ROW_HEIGHT,
    overscan: 8,
    enabled: virtualize,
  });

  usePinnedColumnWidths(tableRef, virtualize);

  const virtualItems = virtualizer.getVirtualItems();
  const padTop = virtualItems.length ? virtualItems[0].start : 0;
  const padBottom = virtualItems.length
    ? virtualizer.getTotalSize() - virtualItems[virtualItems.length - 1].end
    : 0;

  // Which rows to actually render. The dragged row is always included even when it has scrolled
  // out of the window: dnd-kit tracks a live node, and unmounting it mid-drag drops the drag.
  const windowIndexes = virtualize ? virtualItems.map((v) => v.index) : rows.map((_, i) => i);
  const activeIndex = activeDragId ? ids.indexOf(activeDragId) : -1;
  const renderIndexes =
    activeIndex >= 0 && !windowIndexes.includes(activeIndex)
      ? [...windowIndexes, activeIndex].sort((a, b) => a - b)
      : windowIndexes;

  const { sentinelRef } = useInfiniteScroll({ onLoadMore, hasMore, loading: loading || loadingMore });

  return (
    <DndContext {...contextProps}>
      {/* Its own edge, matching the inbox and tree panels: this view is a surface on the shell,
          not a fill of it. `overflow-hidden` keeps the rows clipped to the radius. */}
      <div
        className={cn(
          "bg-background-presentation-form-base flex h-full overflow-hidden",
          "border-border-presentation-global-primary rounded-[16px] border",
          className,
        )}
      >
        <div className="flex flex-1 flex-col gap-4 overflow-hidden">
          {/* The scroller and the end action are stacked here with NO gap, so the bar sits flush
              under the table the way it does on the card. `min-h-0` lets the scroller actually
              shrink — a flex item will not go below its content without it. */}
          <div className="flex min-h-0 flex-1 flex-col">
            <div
              ref={scrollRef}
              // `min-w-0` so the scroller can be narrower than the table inside it. Without it a flex
              // item refuses to shrink below its content, so pinning the table to its natural width
              // pushes the whole component wide instead of scrolling within it.
              className="min-w-0 flex-1 overflow-auto rounded-lg"
            >
              {/* Sizes the table, not the footer — the end action now lives outside this scroller.
                  Inside an `overflow-auto` scroller a child's `w-full` resolves against the *visible*
                  width, so the table needs `w-max` to reach its natural width and scroll; `min-w-full`
                  keeps it filling the scroller when the table is narrower. */}
              <div className="w-max min-w-full">
                {/* `overflow-visible` opts out of the primitive's `overflow-hidden` (tailwind-merge
                  lets ours win). It has to: a clipping table is its own scrollport, and the sticky
                  header would then resolve against a box that never scrolls. Safe here because the
                  scroller above is `min-w-0 overflow-auto`, so a wide table scrolls inside it rather
                  than pushing the layout. */}
                <Table ref={tableRef} className="w-full overflow-visible">
                  {/* The header sticks to the scroller above by default — that lives on `TableHeader`
                    in the primitive. Two things this view adds:

                    Opacity. The primitive's header token is translucent, so scrolling rows read
                    straight through it; the primitive can't fix that without naming a surface colour
                    it doesn't know. Here the surface *is* known — the view root above sets
                    `form-base` — so paint that as the background-color (tailwind-merge drops the
                    primitive's translucent one, same `bg-color` group) and re-apply the tint as a
                    background-image, which stacks above background-color. Composited that is the
                    exact colour the header already had, just no longer see-through.

                    And `shadow-none`, because the drop shadow reads as a seam now that the view
                    carries its own border. */}
                  <TableHeader className="bg-background-presentation-form-base bg-[image:linear-gradient(var(--background-presentation-form-header),var(--background-presentation-form-header))] shadow-none">
                    <TableRow>
                      {onRowMove && <TableHead isDummy className="w-8" />}
                      {selectable && (
                        <TableHead isDummy className="w-12">
                          {/* Size is stated on both this and the per-row checkbox rather than left to
                            `Checkbox`'s default — they have to agree, and relying on the default on
                            one side only is what previously made the select-all bigger than the
                            column it heads. */}
                          <Checkbox
                            size="M"
                            checked={allSelected ? true : someSelected ? "indeterminate" : false}
                            onCheckedChange={toggleAll}
                            aria-label="Select all rows"
                          />
                        </TableHead>
                      )}
                      {/* Keyed by position: two fields may share a `path` — the same value shown two
                      ways — and keying on it would collide. */}
                      {visibleFields.map((field, i) => (
                        <TableHead
                          key={`${field.path}-${i}`}
                          size="M"
                          sortType={sort?.path === field.path ? sort.direction : undefined}
                          onSort={() => setSort(cycle(field.path))}
                          // Without this every sort control announces itself as a bare "Sort ascending",
                          // so a screen reader hears one identical button per column.
                          sortLabel={field.label ?? formatPathLabel(field.path)}
                        >
                          {/* Wrapped rather than handed to `Table` as bare text: `truncate` needs a box
                            to clip, and the label's parent in the primitive is already `flex min-w-0`
                            so this span shrinks and ellipsises instead of wrapping the header row
                            onto a second line. */}
                          <span className="truncate">{field.label ?? field.path}</span>
                        </TableHead>
                      ))}
                    </TableRow>
                  </TableHeader>

                  <TableBody>
                    {loading && <SkeletonRows fields={visibleFields} grip={Boolean(onRowMove)} selectable={selectable} />}
                    {virtualize && padTop > 0 && (
                      <tr aria-hidden style={{ height: padTop }} />
                    )}
                    <DragList ids={ids}>
                      {renderIndexes.map((index) => {
                        const row = rows[index];
                        const id = ids[index];
                        const selected = selection.includes(id);
                        return (
                          <DraggableRow
                            key={id}
                            id={id}
                            draggable={Boolean(onRowMove)}
                            state={selected ? "selected" : undefined}
                            onClick={onRowClick ? () => onRowClick(row, id) : undefined}
                            // A clickable row has to be reachable without a mouse. `<tr>` carries no
                            // implicit role, so a bare `onClick` is invisible to the keyboard and to a
                            // screen reader; these only appear when the row is actually interactive.
                            tabIndex={onRowClick ? 0 : undefined}
                            role={onRowClick ? "button" : undefined}
                            onKeyDown={
                              onRowClick
                                ? (e) => {
                                  if (e.key !== "Enter" && e.key !== " ") return;
                                  if (e.target !== e.currentTarget) return;
                                  e.preventDefault();
                                  onRowClick(row, id);
                                }
                                : undefined
                            }
                            className={cn(
                              // 40px per Figma's `Table-RowBackgroand-1.1`. `Table`'s body cells default
                              // to 50, and the two live on different elements, so the cells below must be
                              // told as well or CSS keeps the larger.
                              "h-[40px]",
                              "focus-visible:ring-border-presentation-state-focus outline-none focus-visible:ring-2",
                              onRowClick && "cursor-pointer",
                            )}
                          >
                            {onRowMove && <GripCell />}
                            {selectable && (
                              <TableCell isDummy className="min-h-[40px] w-12" onClick={(e) => e.stopPropagation()}>
                                {/* What `TableCheckbox` renders, inlined: its props are typed as button
                              attributes, so it cannot express a controlled checkbox. */}
                                <div className="flex items-center justify-center">
                                  <Checkbox
                                    size="M"
                                    checked={selected}
                                    onCheckedChange={() => toggleRow(id)}
                                    aria-label="Select row"
                                  />
                                </div>
                              </TableCell>
                            )}
                            {visibleFields.map((field, i) => {
                              // `undefined` means "you paint it" — distinct from `null`, which is a
                              // deliberate blank.
                              const custom = renderCell?.({ field, row, id, index, fields: visibleFields });
                              // `fade={false}` and clip instead. The fade is a `mask-image` on every
                              // cell, close to free on its own but very expensive once a sticky header
                              // repaints the region each scroll frame: measured on this page,
                              // mask+sticky costs ~61ms/frame against ~29ms with the mask off and
                              // ~17ms with neither. `overflow-hidden` is passed back because
                              // `fade={false}` otherwise switches the cell to `overflow-visible`, and
                              // the text would spill into the next column.
                              return (
                                <TableCell
                                  key={`${field.path}-${i}`}
                                  className="min-h-[40px]"
                                  fade={false}
                                  childrenClassName="overflow-hidden"
                                >
                                  {/* `isolate` confines the Badge's mix-blend-luminosity to a local
                                stacking context and `transform-gpu` promotes it to its own layer, so
                                the table's post-mount column reflow repaints cleanly instead of
                                leaving a ghosted badge frame. */}
                                  <span className="isolate inline-flex transform-gpu">
                                    {custom === undefined ? <Cell field={field} row={row} /> : custom}
                                  </span>
                                </TableCell>
                              );
                            })}
                          </DraggableRow>
                        );
                      })}
                    </DragList>
                    {virtualize && padBottom > 0 && (
                      <tr aria-hidden style={{ height: padBottom }} />
                    )}
                    {/* The trigger. A row of its own rather than an element after the table, so it sits
                    inside the same scroller the rows do. */}
                    {hasMore && !loading && (
                      <tr ref={sentinelRef as React.Ref<HTMLTableRowElement>} aria-hidden>
                        <td style={{ height: 1, padding: 0, border: 0 }} colSpan={100} />
                      </tr>
                    )}
                    {loadingMore && (
                      <SkeletonRows
                        rows={2}
                        fields={visibleFields}
                        grip={Boolean(onRowMove)}
                        selectable={selectable}
                      />
                    )}
                  </TableBody>
                </Table>
              </div>
            </div>
            {/* Outside the scroller, deliberately: as a sibling its width is the component's visible
                width, so it spans the full outer container and stays put while the columns scroll
                sideways under it — instead of stretching to the table's scrollable width and sliding
                away like a normal row. Same placement the form Table field uses. */}
            {onAddRow && (
              <TableEndAction onClick={onAddRow}>
                <Plus className="h-4 w-4" aria-hidden />
                {addRowLabel}
              </TableEndAction>
            )}
          </div>
        </div>
      </div>
    </DndContext>
  );
}

/**
 * A row that can be picked up.
 *
 * `TableRow` forwards its ref, so the `<tr>` itself is the draggable — no wrapper element, which
 * a table would not accept between `<tbody>` and `<tr>` anyway.
 *
 * The drag listeners go on the grip, not the row: a row is clickable, and a row that is also a
 * drag handle makes selecting text or hitting a button inside it a gamble.
 */
function DraggableRow({
  id,
  draggable,
  children,
  ...props
}: React.ComponentProps<typeof TableRow> & { id: string; draggable: boolean }) {
  const { ref, handleProps, style, isDragging } = useDragItem(id, !draggable);

  return (
    <DragHandleContext.Provider value={draggable ? handleProps : null}>
      <TableRow
        ref={ref}
        style={style}
        {...props}
        className={cn(props.className, isDragging && "opacity-40")}
      >
        {children}
      </TableRow>
    </DragHandleContext.Provider>
  );
}

/** The listeners the grip needs, handed down from the row that owns them. */
const DragHandleContext = React.createContext<Record<string, unknown> | null>(null);

/** How many shimmer rows to lay down. Enough to fill the fold — not a guess at what is coming. */
const SKELETON_ROWS = 8;

/** Figma's `Table-RowBackgroand-1.1`. Exact, which is what makes virtualization measurement-free. */
const ROW_HEIGHT = 50;

/**
 * Below this many rows the table renders every one of them, exactly as it always has.
 *
 * Virtualization is not free here: the table is `table-layout: auto` with a 200px per-cell
 * minimum, so column widths are computed from whatever rows are currently mounted. Rendering only
 * a window of them makes the widths change as you scroll — unless they are pinned first, which is
 * what `usePinnedColumnWidths` does. None of that is worth doing to a table of 40 rows.
 */
const VIRTUALIZE_AFTER = 300;

/**
 * Freeze the column widths before the rows start disappearing.
 *
 * The order matters and is the whole difficulty. `table-layout: auto` sizes columns from the rows
 * that are *mounted*, so by the time virtualization has swapped thousands of rows for a window of
 * thirty, the widths have already collapsed to fit that window — measuring then pins the collapsed
 * numbers, and the table ends up about half its width with content spilling between columns. So
 * the widths are remembered on every render while the table is still whole, and those remembered
 * numbers are what get pinned at the moment it stops being whole.
 *
 * The table's own width is pinned too: under `fixed` the column widths are read as proportions of
 * it, and the table is `w-full`, so leaving it alone squeezes every column into the container.
 */
function usePinnedColumnWidths(
  tableRef: React.RefObject<HTMLTableElement | null>,
  virtualize: boolean,
) {
  const naturalWidths = React.useRef<number[] | null>(null);
  const pinned = React.useRef(false);

  // Deliberately no dependency array: the widths have to be re-read as rows accumulate, right up
  // to the render before the threshold is crossed.
  React.useLayoutEffect(() => {
    const table = tableRef.current;
    if (!table) return;
    const heads = [...table.querySelectorAll("thead th")] as HTMLTableCellElement[];

    if (!virtualize) {
      naturalWidths.current = heads.map((th) => th.getBoundingClientRect().width);
      if (pinned.current) {
        table.style.tableLayout = "";
        table.style.removeProperty("width");
        heads.forEach((th) => th.style.removeProperty("width"));
        pinned.current = false;
      }
      return;
    }

    if (pinned.current) return;
    const widths = naturalWidths.current;
    if (!widths || widths.length !== heads.length) return;
    heads.forEach((th, i) => {
      th.style.width = `${widths[i]}px`;
    });
    table.style.width = `${widths.reduce((sum, w) => sum + w, 0)}px`;
    table.style.tableLayout = "fixed";
    pinned.current = true;
  });
}

/**
 * The loading table.
 *
 * Built from the same `TableRow`/`TableCell` a real row uses, with one cell per visible field, so
 * the columns sit at exactly the widths the data will land in and nothing shifts when it does.
 * The header above is untouched — it comes from `visibleFields`, not from `rows`.
 */
function SkeletonRows({
  fields,
  grip,
  selectable,
  rows = SKELETON_ROWS,
}: {
  fields: readonly { path: string }[];
  grip: boolean;
  selectable: boolean;
  rows?: number;
}) {
  return (
    <>
      {skeletonKeys(rows).map((row) => (
        <TableRow key={`skeleton-${row}`} className="h-[40px]">
          {grip && <TableCell isDummy className="h-[40px] w-8" />}
          {selectable && <TableCell isDummy className="h-[40px] w-12" />}
          {fields.map((field, i) => (
            <TableCell
              key={`${field.path}-${i}`}
              className="min-h-[40px]"
              fade={false}
              childrenClassName="overflow-hidden"
            >
              {/* Widths cycle rather than repeat, so a column of bars reads as text that has not
                  arrived instead of as a grid. */}
              <SkeletonBar className={["w-[70%]", "w-[45%]", "w-[85%]", "w-[60%]"][(row + i) % 4]} />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

/** The 2×3 grip. Only rendered when the table is reorderable. */
function GripCell() {
  const handleProps = React.useContext(DragHandleContext);
  return (
    <TableCell isDummy className="h-[40px] w-8" onClick={(e) => e.stopPropagation()}>
      <span
        {...handleProps}
        aria-label="Reorder row"
        className={cn(
          "text-content-presentation-global-tertiary flex cursor-grab items-center justify-center",
          "active:cursor-grabbing",
        )}
      >
        <i className="ri-draggable text-[16px]" aria-hidden />
      </span>
    </TableCell>
  );
}

export const TableView = markView(TableViewImpl, {
  defaultId: "table",
  defaultLabel: "List",
});

"use client";

import React, { useMemo } from "react";
import { cn } from "../../../utils/cn";
import { getByPath } from "../../../utils/dataViews/path";
import type { FieldConfig, Row, TreeNode } from "../../../utils/dataViews/types";
import { TreeFolder, type TreeFolderNode } from "../../TreeFolder";
import { TabSwitch } from "../../TabSwitch";
import {
  PaneCards,
  PaneTab,
  PaneTable,
  TreePaneProvider,
  flattenChildren,
  isPaneViewElement,
  paneViewOption,
  type PaneViewElement,
} from "./pane-views";
import { SkeletonBar } from "../states";
import { useControllable } from "../hooks/useControllable";
import { DataContext, useDataViewsData, useDataViewsView } from "../context";
import { markView } from "../slots";
import type { TreePaneMode, TreeViewProps } from "../types";

/** Depth-first lookup by id. The tree is a shape the caller built, so there is no index to keep. */
function findNode(nodes: readonly TreeNode[], id: string | null): TreeNode | null {
  if (!id) return null;
  for (const node of nodes) {
    if (node.id === id) return node;
    const hit = findNode(node.children, id);
    if (hit) return hit;
  }
  return null;
}

/**
 * The pane beside the tree — the selected node's rows, in whichever tab is showing.
 *
 * The pane holds three things and owns none of them: a header (the node's name, its record count,
 * your `paneActions`), a switch built from the tabs you rendered, and the tabs themselves. Each
 * tab decides on its own whether it is the one showing, so adding a mode is rendering a component
 * rather than extending a union here.
 *
 * Both scopes the tabs need are set up here: rows swapped to the node's, so a tab's
 * `useDataViewsData()` sees what the pane lists rather than the whole set; and the mode, so each
 * tab can self-select.
 */
function TreePane({
  node,
  rows,
  labelField,
  mode,
  onModeChange,
  actions,
  tabs,
}: {
  node: TreeNode | null;
  rows: readonly Row[];
  labelField?: FieldConfig;
  mode: TreePaneMode;
  onModeChange: (mode: TreePaneMode) => void;
  actions?: TreeViewProps["paneActions"];
  tabs: PaneViewElement[];
}) {
  const data = useDataViewsData();

  // The pane paints a different row set from the root's, and everything inside it reads `rows`
  // from context — so the swap happens here, once, rather than as a prop on each child.
  const scoped = useMemo(() => ({ ...data, rows }), [data, rows]);
  const paneCtx = useMemo(() => ({ mode: String(mode), labelField }), [mode, labelField]);

  // The title is the node's label as a **string**, not a `Cell`. A label field of kind
  // `enum-badge` would paint a Badge chip, and a chip inside display-size uppercase type is not a
  // title — it is a chip in the wrong place.
  const title =
    (node && labelField ? String(getByPath(node.row, labelField.path) ?? "") : "") || "Items";

  const options = tabs.map(paneViewOption);

  return (
    <DataContext.Provider value={scoped}>
      <TreePaneProvider value={paneCtx}>
        <div className="flex min-h-0 flex-1 flex-col">
          {/* The header belongs to the pane, not to the selection: it stays up with nothing chosen
              so the switch is reachable and the pane is not a blank rounded box. Same
              `display-medium-medium` + `uppercase` + `cv05` recipe as the rail's own header band,
              so the two read as one row across the screen. */}
          <div className="border-border-presentation-global-primary flex shrink-0 items-center justify-between gap-2 border-b px-3 py-2">
            {/* `min-w-0` on the left group is what makes the title truncate before the switch
                starts shrinking. */}
            <div className="flex min-w-0 items-center gap-2">
              <span
                style={{ fontFeatureSettings: "'cv05' on" }}
                className="typography-display-medium-medium text-content-presentation-global-primary truncate uppercase"
              >
                {title}
              </span>
              <div className="bg-border-presentation-global-primary h-6 w-px shrink-0" />
              <span className="typography-body-medium-regular text-content-presentation-global-secondary truncate">
                {node ? `${rows.length} record${rows.length === 1 ? "" : "s"}` : "Select an item"}
              </span>
            </div>

            <div className="flex shrink-0 items-center gap-2">
              {/* Your slot, before the switch so the switch keeps the corner it is drawn in. */}
              {actions}

              {/* One tab is a label, not a choice — the same rule `ViewSwitch` follows. The
                  `TabSwitch` default size is 24px tall with 14px icons, the metrics this pane is
                  drawn at, and it takes no `theme`: unlike `ViewSwitch` on the dark header bar,
                  the pane sits in the light content area. */}
              {options.length > 1 && (
                <TabSwitch
                  options={options}
                  value={String(mode)}
                  onValueChange={(next) => onModeChange(next)}
                />
              )}
            </div>
          </div>

          {/* Nothing selected is shown as nothing — the header already says "Select an item". */}
          <div className="min-h-0 flex-1 overflow-auto">{node ? tabs : null}</div>
        </div>
      </TreePaneProvider>
    </DataContext.Provider>
  );
}

/** The tree's own metrics, so a skeleton row occupies exactly what a real node will. */
const TREE_ROW_HEIGHT = 28;
const TREE_INDENT = 14;
const SKELETON_NODES = [0, 1, 1, 0, 1, 1, 0] as const;

/**
 * The loading tree.
 *
 * Depths alternate so it reads as a hierarchy rather than a list, and each row is `TreeFolder`'s
 * own 28px at its 14px indent — the nodes land exactly where the shimmer was.
 */
function SkeletonNodes() {
  return (
    <div className="flex flex-col px-2 py-1">
      {SKELETON_NODES.map((depth, i) => (
        <div
          key={`skeleton-${i}`}
          className="flex items-center gap-2"
          style={{ height: TREE_ROW_HEIGHT, paddingInlineStart: 6 + depth * TREE_INDENT }}
        >
          <SkeletonBar className="h-[14px] w-[14px] shrink-0 rounded-[3px]" />
          <SkeletonBar className={depth === 0 ? "w-[60%]" : "w-[45%]"} />
        </div>
      ))}
    </div>
  );
}

/**
 * `DataViews.Tree` — a hierarchy on the left, whatever you put in `children` on the right.
 *
 * The rail is the shared `TreeFolder`, which is where the row height, the indent, the connector
 * lines, the selection band, the breadcrumb and the drag grip come from. Hand-rolling those is how
 * this view stops looking like the file tree everywhere else in the product.
 *
 * You build `nodes`. The tree never derives a hierarchy from flat rows: which field is the parent
 * key, whether orphans become roots, how cycles are handled — those are decisions only you can
 * make correctly, and guessing them was most of what the old implementation got wrong.
 */
function TreeViewImpl({
  nodes,
  labelPath,
  renderNode,
  expanded,
  onExpandedChange,
  onNodeMove,
  paneMode,
  defaultPaneMode,
  onPaneModeChange,
  paneRows,
  paneActions,
  children,
  className,
}: TreeViewProps) {
  const { visibleFields, loading } = useDataViewsData();
  // Selection is the root's `activeId`, the same one the inbox and board use — so a detail pane
  // works the same wherever it is rendered, and there is one "what is selected" in the component.
  const { activeId, setActiveId } = useDataViewsView();

  const labelField =
    (labelPath && visibleFields.find((f) => f.path === labelPath)) || visibleFields[0];

  const [openIds, setOpenIds] = useControllable<readonly string[]>(
    expanded,
    onExpandedChange,
    nodes.filter((n) => n.children.length > 0).map((n) => n.id),
  );

  const folderData = useMemo(
    () => nodes.map((node) => toFolderNode(node, labelField, visibleFields, renderNode)),
    [nodes, labelField, visibleFields, renderNode],
  );

  // ── The pane ──────────────────────────────────────────────────────────────

  /**
   * Children split two ways: the pane's tabs, and everything else.
   *
   * Everything else *is* the pane — the whole-pane override, header and switch included, which is
   * what every tree written before these tabs existed passes.
   *
   * Pass **nothing** and there is no pane at all: a part exists because you rendered it, and the
   * pane is no more exempt from that than the table or the rail. A tree with no tabs is a
   * hierarchy, and it takes the whole width.
   */
  const { tabs, override } = useMemo(() => {
    const all = flattenChildren(children);
    return {
      tabs: all.filter(isPaneViewElement),
      override: all.filter((child) => !isPaneViewElement(child)),
    };
  }, [children]);

  const hasPane = override.length > 0 || tabs.length > 0;

  // The starting mode is the **first tab's**, not a hardcoded `"table"` — a pane whose only tab is
  // yours has to open on it, and would otherwise sit blank on a `"table"` that matches nothing and
  // is not reachable, since one tab draws no switch.
  const [mode, setMode] = useControllable(
    paneMode,
    onPaneModeChange,
    defaultPaneMode ?? (tabs[0] ? paneViewOption(tabs[0]).value : ""),
  );

  const selectedNode = useMemo(() => findNode(nodes, activeId), [nodes, activeId]);

  /**
   * What the pane lists. A branch shows what is **under** it — a synthetic grouping node has no
   * meaningful row of its own — and a leaf, having no descendants, shows itself.
   */
  const paneRowsForNode = useMemo<readonly Row[]>(() => {
    if (!selectedNode) return [];
    if (paneRows) return paneRows(selectedNode);
    const out: Row[] = [];
    const walk = (node: TreeNode) => {
      for (const child of node.children) {
        out.push(child.row);
        walk(child);
      }
    };
    walk(selectedNode);
    return out.length > 0 ? out : [selectedNode.row];
  }, [selectedNode, paneRows]);

  return (
    // A split view, so the gap between the rail and the pane is part of the design: it paints the
    // shell's black over the Master Container's surface, and the two cards float on it. The board
    // fills its container instead — the table now carries its own border, like these panels.
    <div className={cn("flex h-full gap-2 bg-black", className)}>
      <div
        className={cn(
          "border-border-presentation-global-primary bg-background-presentation-form-base flex flex-col overflow-hidden rounded-[16px] border",
          // Beside a pane the rail is a fixed 256px column; with no pane there is nothing to
          // divide the width with, so it takes all of it.
          hasPane ? "w-64 shrink-0" : "min-w-0 flex-1",
        )}
      >
        <div className="border-border-presentation-global-primary border-b px-3 py-2">
          {/* `block` before `truncate` — the parent is a plain div, so an inline span would clip
              nothing. Same reason as the inbox's panel header. */}
          <span
            style={{ fontFeatureSettings: "'cv05' on" }}
            className="typography-display-medium-medium text-content-presentation-global-primary block truncate uppercase"
          >
            {labelField?.label ?? "categories"}
          </span>
        </div>
        <div className="flex-1 overflow-hidden">
          {loading ? (
            <SkeletonNodes />
          ) : (
          <TreeFolder
            data={folderData}
            selectedId={activeId}
            onSelectionChange={(id) => setActiveId(id ?? null)}
            expandedIds={[...openIds]}
            onExpandedChange={(next) => setOpenIds(next)}
            dndEnabled={Boolean(onNodeMove)}
            onMove={({ dragIds, parentId, index }) =>
              // `TreeFolder` reports a drop as "these ids, into this parent, at this index".
              // `MoveIntent` is one row at a time, so a multi-select drag emits one intent each.
              dragIds.forEach((id) => onNodeMove?.({ id, from: null, to: parentId, index }))
            }
            showHeader={false}
            showBreadcrumb
            highlightAncestors
          />
          )}
        </div>
      </div>

      {/* No tabs and no pane of your own means no pane — not an empty one. */}
      {hasPane && (
        <div className="border-border-presentation-global-primary bg-background-presentation-form-base flex min-w-0 flex-1 flex-col overflow-hidden rounded-[16px] border">
          {/* A pane of your own still wins outright — see the split above. */}
          {override.length > 0 ? (
            override
          ) : (
            <TreePane
              node={selectedNode}
              rows={paneRowsForNode}
              mode={mode}
              onModeChange={setMode}
              labelField={labelField}
              actions={paneActions}
              tabs={tabs}
            />
          )}
        </div>
      )}
    </div>
  );
}

/** A `TreeNode` painted the way the rail wants it: a name, and folder-vs-file by having children. */
function toFolderNode(
  node: TreeNode,
  labelField: FieldConfig | undefined,
  fields: readonly FieldConfig[],
  renderNode: TreeViewProps["renderNode"],
): TreeFolderNode {
  const labelValue = labelField ? getByPath(node.row, labelField.path) : undefined;
  const children = node.children.length
    ? node.children.map((c) => toFolderNode(c, labelField, fields, renderNode))
    : undefined;

  // The row belongs to `TreeFolder` — indent, connectors, selection band, drag grip. What a
  // caller can vary is what sits *in* it, so this takes the three slots rather than markup.
  const custom = renderNode?.({ node, row: node.row, fields });

  return {
    id: node.id,
    name: custom?.name ?? (labelValue == null ? node.id : String(labelValue)),
    icon: custom?.icon,
    meta: custom?.meta,
    type: children ? "folder" : "file",
    data: node.row,
    children,
  };
}

/**
 * The tree, with its pane's tabs hanging off it — `DataViews.Tree.Table`, `.Cards` and `.Tab`.
 * They live here rather than on the root because they are the *pane's* views, not the
 * component's: rendering `DataViews.Table` adds a tab to the header's switcher, rendering
 * `DataViews.Tree.Table` adds one to the pane's.
 */
export const TreeView = Object.assign(
  markView(TreeViewImpl, {
    defaultId: "tree",
    defaultLabel: "Tree",
  }),
  {
    Table: PaneTable,
    Cards: PaneCards,
    Tab: PaneTab,
  },
);
